/* IT : lot réseau — DNS, réseau pour Microsoft 365, VPN, VLAN et routage, diagnostic. Au moins 20 questions par niveau et par sous-thème. */
window.QUESTIONS.push(
  {"theme":"dns","level":"recrue","format":"single","q":"Que fait principalement le DNS ?","a":["Il traduit un nom de domaine en adresse IP","Il filtre les paquets selon des règles de sécurité","Il chiffre les échanges entre le navigateur et le site","Il attribue automatiquement une adresse IP à chaque poste"],"g":0,"e":"Le DNS (Domain Name System) est l'annuaire d'Internet : il retrouve l'adresse IP correspondant à un nom comme www.exemple.fr. L'attribution automatique des adresses est le rôle du DHCP."},
  {"theme":"dns","level":"recrue","format":"single","q":"Sur quel port les requêtes DNS classiques sont-elles envoyées ?","a":["Le port 443","Le port 53","Le port 67","Le port 25"],"g":1,"e":"Le DNS écoute sur le port 53, en UDP pour les requêtes courantes et en TCP pour les réponses volumineuses et les transferts de zone. Le 25 est celui de SMTP, le 67 celui de DHCP et le 443 celui de HTTPS."},
  {"theme":"dns","level":"recrue","format":"single","q":"Quel enregistrement DNS associe un nom à une adresse IPv4 ?","a":["L'enregistrement MX","L'enregistrement AAAA","L'enregistrement A","L'enregistrement PTR"],"g":2,"e":"L'enregistrement A associe un nom à une adresse IPv4. Son équivalent pour IPv6 est AAAA, MX désigne le serveur de messagerie et PTR sert à la résolution inverse."},
  {"theme":"dns","level":"recrue","format":"single","q":"Quel enregistrement DNS indique quel serveur reçoit les mails d'un domaine ?","a":["L'enregistrement NS","L'enregistrement SOA","L'enregistrement SRV","L'enregistrement MX"],"g":3,"e":"MX (Mail eXchanger) désigne le ou les serveurs de messagerie d'un domaine, avec une priorité. Sans enregistrement MX correct, les mails ne sont pas livrés."},
  {"theme":"dns","level":"recrue","format":"single","q":"À quoi sert un enregistrement CNAME ?","a":["À créer un alias : un nom qui pointe vers un autre nom","À retrouver le nom associé à une adresse IP donnée","À désigner le serveur de messagerie d'un domaine","À publier du texte libre, par exemple une règle SPF"],"g":0,"e":"Un CNAME (nom canonique) redirige un nom vers un autre nom, par exemple www.exemple.fr vers exemple.fr. Le texte libre est le rôle du TXT et la résolution inverse celui du PTR."},
  {"theme":"dns","level":"recrue","format":"single","q":"Que signifie le sigle FQDN ?","a":["Fast Qualified DNS Network : un réseau de serveurs DNS optimisé pour la rapidité","Fully Qualified Domain Name : le nom complet d'une machine, par exemple pc01.entreprise.local","Forwarded Query Domain Node : un serveur DNS relais qui transmet les requêtes vers Internet","First Query Domain Name : la première requête DNS envoyée par un poste après son démarrage"],"g":1,"e":"Un FQDN désigne le nom complet d'une machine, du nom d'hôte jusqu'à la racine : pc01.entreprise.local. Il n'est pas ambigu, contrairement au nom court pc01."},
  {"theme":"dns","level":"recrue","format":"single","q":"Dans « www.exemple.fr », quelle partie est le domaine de premier niveau (TLD) ?","a":["exemple","exemple.fr","www",".fr"],"g":3,"e":"Le TLD (Top Level Domain) est la dernière partie du nom : .fr, .com, .org… « exemple.fr » est le domaine, « www » le nom d'hôte."},
  {"theme":"dns","level":"recrue","format":"single","q":"Comment les postes d'une entreprise connaissent-ils l'adresse de leur serveur DNS ?","a":["Elle est définie une fois pour toutes dans le navigateur lors de son installation","Le commutateur (switch) la diffuse automatiquement à tous les postes connectés","Le plus souvent, le serveur DHCP la leur fournit en même temps que leur adresse IP","Le serveur de messagerie la communique à chaque poste lors de l'ouverture de session"],"g":2,"e":"Le DHCP distribue l'adresse IP, le masque, la passerelle et les serveurs DNS (option 6). On peut aussi les saisir à la main sur un serveur ou un poste en adresse fixe."},
  {"theme":"dns","level":"recrue","format":"single","q":"Quel fichier permet d'associer localement un nom à une adresse IP, sans interroger de serveur DNS ?","a":["Le fichier pagefile.sys","Le fichier hosts","Le fichier services","Le fichier ntuser.dat"],"g":1,"e":"Le fichier hosts (C:\\Windows\\System32\\drivers\\etc\\hosts sous Windows, /etc/hosts sous Linux) est consulté avant le DNS. Le fichier services, voisin du premier, associe des noms à des numéros de port."},
  {"theme":"dns","level":"recrue","format":"single","q":"Un site s'ouvre en tapant son adresse IP, mais pas avec son nom. Quelle piste est la plus probable ?","a":["Un problème de résolution DNS, pas de connexion réseau","La carte réseau du poste n'a plus d'adresse IP valide","Le pare-feu bloque tout le trafic sortant du poste","Le câble réseau est débranché ou la carte réseau est désactivée"],"g":0,"e":"Si l'IP répond, la connexion réseau fonctionne. Le nom, lui, doit être traduit par le DNS : c'est donc lui qu'il faut vérifier (serveur configuré, cache, enregistrement)."},
  {"theme":"dns","level":"recrue","format":"single","q":"Quel est le rôle d'un serveur DNS secondaire ?","a":["Remplacer le serveur DHCP lorsqu'il tombe en panne","Chiffrer les échanges entre le poste et le serveur principal","Répondre aux requêtes avec une copie de la zone du serveur principal, pour assurer la redondance","Stocker uniquement les adresses MAC des postes du réseau"],"g":2,"e":"Le serveur secondaire reçoit la zone par transfert depuis le principal. Si ce dernier est indisponible, la résolution continue."},
  {"theme":"dns","level":"recrue","format":"single","q":"Où réserve-t-on un nom de domaine comme exemple.fr ?","a":["Dans la console d'administration du pare-feu","Dans les paramètres réseau de chaque poste","Auprès du fabricant du routeur de l'entreprise","Auprès d'un bureau d'enregistrement (registrar)"],"g":3,"e":"Un nom de domaine se réserve auprès d'un bureau d'enregistrement accrédité, qui le déclare dans le registre du TLD. On gère ensuite la zone chez lui ou chez un autre hébergeur DNS."},
  {"theme":"dns","level":"recrue","format":"tf","q":"Un enregistrement CNAME peut pointer directement vers une adresse IP.","a":["Vrai","Faux"],"g":1,"e":"Faux : un CNAME pointe vers un autre nom. Pour désigner une adresse IP, on utilise un enregistrement A (IPv4) ou AAAA (IPv6)."},
  {"theme":"dns","level":"recrue","format":"tf","q":"Le DNS ne sert qu'à naviguer sur le web.","a":["Vrai","Faux"],"g":1,"e":"Faux : le DNS est utilisé par la messagerie (MX), Active Directory (SRV), Teams, les applications métier… Presque tout service réseau s'appuie sur lui."},
  {"theme":"dns","level":"recrue","format":"tf","q":"Le TTL d'un enregistrement DNS indique pendant combien de temps, en secondes, une réponse peut être gardée en cache.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le TTL (Time To Live) fixe la durée de vie en cache. Un TTL court permet de changer vite, au prix de plus de requêtes."},
  {"theme":"dns","level":"recrue","format":"multi","q":"Quels outils permettent d'interroger un serveur DNS ? (plusieurs réponses)","a":["dig","nslookup","netstat","tracert"],"g":[0,1],"e":"nslookup (Windows, Linux) et dig (Linux, macOS) interrogent un serveur DNS. tracert suit le chemin des paquets et netstat liste les connexions."},
  {"theme":"dns","level":"recrue","format":"multi","q":"Quelles informations un serveur DHCP peut-il fournir au poste en plus de son adresse IP ? (plusieurs réponses)","a":["La passerelle par défaut","L'adresse du ou des serveurs DNS","Le mot de passe Wi-Fi","La liste des utilisateurs du domaine"],"g":[0,1],"e":"Un bail DHCP contient notamment le masque, la passerelle, les serveurs DNS et le suffixe DNS. Il ne distribue ni mots de passe ni comptes."},
  {"theme":"dns","level":"recrue","format":"order","q":"Remets dans l'ordre ce qui se passe quand tu tapes www.exemple.fr dans ton navigateur :","items":["Le navigateur demande l'adresse IP au serveur DNS configuré","Le serveur DNS répond avec l'adresse IP du site","Le navigateur ouvre une connexion vers cette adresse IP","La page s'affiche"],"e":"Le nom est d'abord traduit en adresse IP par le DNS. Le navigateur peut ensuite se connecter au serveur web."},
  {"theme":"dns","level":"recrue","format":"input","q":"Quelle commande, disponible sous Windows, interroge un serveur DNS pour obtenir l'adresse d'un nom ?","placeholder":"Nom de la commande","answers":["nslookup","nslookup.exe","Resolve-DnsName"],"e":"nslookup est installé par défaut sous Windows : nslookup www.exemple.fr affiche le serveur interrogé et l'adresse trouvée."},
  {"theme":"dns","level":"recrue","format":"input","q":"Quel type d'enregistrement DNS associe un nom à une adresse IPv6 ?","placeholder":"Type d'enregistrement","answers":["AAAA","enregistrement AAAA","record AAAA"],"e":"L'enregistrement AAAA (quatre A) porte l'adresse IPv6, car elle est quatre fois plus longue qu'une adresse IPv4 (128 bits contre 32)."},
  {"theme":"dns","level":"hero","format":"single","q":"Quel enregistrement permet de retrouver un nom à partir d'une adresse IP (résolution inverse) ?","a":["L'enregistrement PTR","L'enregistrement CNAME","L'enregistrement SRV","L'enregistrement A"],"g":0,"e":"PTR (pointer) est stocké dans une zone inverse : l'adresse 192.168.0.1 correspond au nom 1.0.168.192.in-addr.arpa, dans la zone 0.168.192.in-addr.arpa. Les serveurs de messagerie et les journaux s'en servent pour afficher des noms plutôt que des adresses."},
  {"theme":"dns","level":"hero","format":"single","q":"Après un changement d'hébergeur, les mails du domaine n'arrivent plus. Quel enregistrement vérifier en premier ?","a":["L'enregistrement A du site web","Les enregistrements MX","Les enregistrements PTR","L'enregistrement CNAME de www"],"g":1,"e":"Les MX indiquent où livrer les mails. Si l'ancien hébergeur est encore désigné, ou si le MX a disparu, les messages se perdent ou sont refusés."},
  {"theme":"dns","level":"hero","format":"single","q":"Où publie-t-on la règle SPF d'un domaine ?","a":["Dans un enregistrement CNAME","Dans un enregistrement MX","Dans un enregistrement PTR","Dans un enregistrement TXT"],"g":3,"e":"SPF, comme DKIM et DMARC, se publie sous forme de texte dans un enregistrement TXT. Il liste les serveurs autorisés à envoyer du courrier pour le domaine."},
  {"theme":"dns","level":"hero","format":"single","q":"Quelle est la différence entre un serveur DNS faisant autorité et un résolveur récursif ?","a":["Le premier utilise uniquement TCP pour répondre, le second uniquement UDP pour interroger","Le premier ne répond qu'aux requêtes venant du réseau interne ; le second répond uniquement à celles qui viennent d'Internet","Le premier détient les enregistrements d'une zone ; le second cherche la réponse pour le compte du client","Le premier chiffre toutes ses réponses avec DNSSEC, le second renvoie des réponses non signées"],"g":2,"e":"Un serveur faisant autorité connaît sa zone et répond de façon définitive. Un résolveur (celui du fournisseur d'accès ou de l'entreprise) interroge les autres serveurs et garde les réponses en cache."},
  {"theme":"dns","level":"hero","format":"single","q":"Pourquoi une modification DNS peut-elle mettre des heures à être visible partout ?","a":["Les résolveurs gardent l'ancienne réponse en cache jusqu'à la fin du TTL","Chaque navigateur doit être redémarré pour relire la zone modifiée","Les modifications ne sont publiées qu'une fois par mois par le registre","Les serveurs racine ne se mettent à jour qu'une fois par jour pour toute la zone"],"g":0,"e":"Tant que le TTL n'est pas écoulé, les caches répondent avec l'ancienne valeur. C'est pourquoi on baisse le TTL avant une migration."},
  {"theme":"dns","level":"hero","format":"single","q":"Quels enregistrements permettent aux postes de trouver les contrôleurs de domaine Active Directory ?","a":["Les enregistrements PTR de chaque poste du domaine","Le fichier hosts présent sur chaque contrôleur","Les enregistrements MX du domaine, côté messagerie","Les enregistrements SRV (par exemple _ldap._tcp.dc._msdcs)"],"g":3,"e":"Active Directory publie ses services dans le DNS sous forme d'enregistrements SRV (LDAP, Kerberos…). Sans DNS correct, un poste ne peut pas ouvrir de session de domaine."},
  {"theme":"dns","level":"hero","format":"single","q":"Un poste du domaine n'arrive plus à joindre le contrôleur de domaine. Son DNS est réglé sur 8.8.8.8. Que corriger ?","a":["Remplacer 8.8.8.8 par 1.1.1.1, un autre résolveur public réputé plus fiable","Désactiver IPv6 sur la carte réseau du poste pour forcer l'usage d'IPv4","Le faire pointer vers le serveur DNS interne, qui héberge la zone Active Directory","Réinstaller le client VPN et réinitialiser le profil réseau du poste"],"g":2,"e":"Un DNS public ne connaît pas la zone interne ni les enregistrements SRV du domaine. Les postes doivent interroger les DNS internes, qui transmettent le reste à Internet."},
  {"theme":"dns","level":"hero","format":"single","q":"Que fait un redirecteur (forwarder) DNS ?","a":["Il copie périodiquement l'intégralité de la zone vers un serveur DNS secondaire de l'entreprise","Il transmet à un autre serveur DNS les requêtes que le serveur local ne sait pas résoudre","Il signe numériquement tous les enregistrements de la zone avec une clé DNSSEC","Il convertit les requêtes DNS en requêtes DHCP pour les postes sans adresse"],"g":1,"e":"Un serveur DNS d'entreprise résout ses zones internes et envoie le reste (Internet) à un redirecteur, par exemple celui du fournisseur d'accès ou un résolveur public."},
  {"theme":"dns","level":"hero","format":"single","q":"Comment un serveur DNS principal peut-il prévenir ses secondaires qu'une zone vient d'être modifiée, sans attendre le délai Refresh du SOA ?","a":["En leur envoyant un message NOTIFY, qui déclenche une vérification du numéro de série puis un transfert","En diffusant la zone complète en broadcast sur le réseau local","En baissant automatiquement le TTL de tous les enregistrements","En redémarrant le service DNS des serveurs secondaires à distance"],"g":0,"e":"Le mécanisme NOTIFY (RFC 1996) avertit les secondaires d'un changement : ils comparent le numéro de série du SOA et demandent un transfert (IXFR ou AXFR) s'il a augmenté. Sans NOTIFY, ils attendent l'intervalle Refresh."},
  {"theme":"dns","level":"hero","format":"single","q":"Quel suffixe DNS Windows ajoute-t-il à un nom court comme SRV01 quand le poste est joint au domaine ?","a":["Le suffixe .com par défaut, ajouté automatiquement par Windows","Le suffixe DNS principal du domaine, par exemple entreprise.local","Le nom du site Active Directory auquel appartient le poste, par exemple Paris-Siege","Le nom NetBIOS du poste, suivi du nom de l'utilisateur connecté"],"g":1,"e":"Windows complète les noms courts avec le suffixe DNS du poste (et la liste de suffixes configurée). SRV01 devient ainsi srv01.entreprise.local."},
  {"theme":"dns","level":"hero","format":"single","q":"Comment sont répliquées les modifications d'une zone DNS intégrée à Active Directory ?","a":["Par un transfert de zone planifié vers chaque poste du domaine","Par DHCP, à chaque renouvellement de bail des postes clients","Par un script PowerShell à écrire puis planifier soi-même","Par la réplication Active Directory, entre les contrôleurs de domaine"],"g":3,"e":"Une zone intégrée est stockée dans l'annuaire : elle bénéficie de la réplication AD et peut être modifiée sur n'importe quel contrôleur, contrairement à une zone classique à serveur principal unique."},
  {"theme":"dns","level":"hero","format":"tf","q":"Les serveurs DNS racine connaissent directement l'adresse IP de www.exemple.fr.","a":["Vrai","Faux"],"g":1,"e":"Faux : la racine ne connaît que les serveurs des domaines de premier niveau. Elle renvoie vers les serveurs de .fr, qui renvoient vers ceux d'exemple.fr."},
  {"theme":"dns","level":"hero","format":"tf","q":"Un serveur DNS secondaire récupère sa zone auprès du serveur principal grâce à un transfert de zone.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le secondaire interroge le principal (SOA, numéro de série) et demande un transfert (AXFR ou IXFR) quand la zone a changé."},
  {"theme":"dns","level":"hero","format":"multi","q":"Un nom ne se résout pas, mais l'adresse IP de la machine répond au ping. Quelles causes sont plausibles ? (plusieurs réponses)","a":["Le poste a une adresse en 169.254.x.x et aucun accès réseau","L'enregistrement A n'existe pas dans la zone","Le poste utilise un serveur DNS injoignable","Le câble réseau est débranché"],"g":[1,2],"e":"Si le ping par IP répond, le réseau fonctionne. Reste le DNS : serveur inaccessible ou enregistrement manquant. Un câble débranché ou une adresse APIPA couperaient aussi le ping."},
  {"theme":"dns","level":"hero","format":"multi","q":"Que contient l'enregistrement SOA d'une zone ? (plusieurs réponses)","a":["Les délais de rafraîchissement et de nouvelle tentative des secondaires","L'adresse IP du pare-feu","La liste des utilisateurs autorisés à modifier la zone","Le numéro de série de la zone"],"g":[0,3],"e":"Le SOA (Start of Authority) décrit la zone : serveur principal, contact, numéro de série, délais (refresh, retry, expire) et TTL négatif."},
  {"theme":"dns","level":"hero","format":"order","q":"Remets dans l'ordre la création d'un enregistrement A pour un nouveau serveur web :","items":["Choisir le nom et l'adresse IP du serveur","Créer l'enregistrement A dans la zone","Vérifier que le numéro de série a augmenté et que les secondaires ont reçu la zone","Tester la résolution avec nslookup"],"e":"On crée l'enregistrement, on s'assure que tous les serveurs faisant autorité le publient (série du SOA, transfert de zone), puis on vérifie la résolution depuis un poste. Si le nom a été demandé avant sa création, un résolveur peut garder un NXDOMAIN en cache négatif quelques minutes."},
  {"theme":"dns","level":"hero","format":"input","q":"Quel type d'enregistrement DNS publie les serveurs de noms d'une zone ? (deux lettres)","placeholder":"Type d'enregistrement","answers":["NS","enregistrement NS"],"e":"Les enregistrements NS (Name Server) désignent les serveurs qui font autorité pour une zone. On en publie au moins deux."},
  {"theme":"dns","level":"hero","format":"input","q":"Quelle commande Windows affiche le contenu du cache DNS du poste ?","placeholder":"Commande","answers":["ipconfig /displaydns","ipconfig/displaydns","Get-DnsClientCache"],"e":"ipconfig /displaydns liste les noms résolus récemment avec leur TTL restant. ipconfig /flushdns les efface."},
  {"theme":"dns","level":"hero","format":"input","q":"Quelle cmdlet PowerShell permet de résoudre un nom, à la manière de nslookup ?","placeholder":"Cmdlet","answers":["Resolve-DnsName"],"e":"Resolve-DnsName exemple.fr -Type MX interroge le DNS et renvoie des objets exploitables dans un script."},
  {"theme":"dns","level":"hero","format":"input","q":"Quelle cmdlet PowerShell vide le cache DNS du client ?","placeholder":"Cmdlet","answers":["Clear-DnsClientCache"],"e":"Clear-DnsClientCache est l'équivalent PowerShell de ipconfig /flushdns. Get-DnsClientCache affiche le contenu du cache."},
  {"theme":"dns","level":"super","format":"single","q":"Une société utilise le même nom de domaine en interne et sur Internet, avec des réponses différentes selon l'origine. Comment appelle-t-on cela ?","a":["Un DNS à horizon partagé (split-horizon ou split-brain)","Un DNS à répartition de charge, de type round robin","Un DNS dynamique (DDNS) mis à jour par les clients","Un transfert de zone incrémentiel entre deux serveurs"],"g":0,"e":"Avec un split-horizon, les postes internes obtiennent les adresses privées des serveurs et le reste du monde les adresses publiques. Il faut penser à maintenir les deux zones."},
  {"theme":"dns","level":"super","format":"single","q":"Quel mécanisme envoie les requêtes d'un domaine précis, par exemple partenaire.local, vers un serveur DNS dédié ?","a":["Un enregistrement SRV spécifique","Un redirecteur conditionnel","Une option DHCP spécifique","Un transfert de zone sécurisé"],"g":1,"e":"Un redirecteur conditionnel (conditional forwarder) applique une règle par domaine, utile pour joindre un partenaire ou un autre réseau interne sans copier sa zone."},
  {"theme":"dns","level":"super","format":"single","q":"Pourquoi ne peut-on pas, selon la norme DNS, placer un CNAME à la racine d'une zone (exemple.fr) ?","a":["Parce que les CNAME sont limités à trois niveaux de chaînage dans toute zone, racine comprise","Parce que le registre du TLD l'interdit dans ses règles de délégation de domaines","Parce que les CNAME ne fonctionnent qu'avec IPv6 et que la racine est servie en IPv4","Parce que la racine porte déjà des enregistrements (SOA, NS, MX) incompatibles avec un CNAME"],"g":3,"e":"Un CNAME doit être le seul enregistrement d'un nom. Or l'apex de la zone doit porter SOA et NS. Certains hébergeurs proposent des « ALIAS » ou « ANAME » non standard pour contourner cela."},
  {"theme":"dns","level":"super","format":"single","q":"Un client reçoit un code NXDOMAIN. Que signifie-t-il ?","a":["La réponse est trop grande et doit être redemandée en TCP","Le serveur DNS est injoignable","Le nom demandé n'existe pas dans le DNS","Le serveur refuse de répondre à ce client"],"g":2,"e":"NXDOMAIN (Non-Existent Domain) est une réponse valide : le nom n'existe pas. Une injoignabilité donne un délai dépassé, un refus donne REFUSED, une troncature le bit TC."},
  {"theme":"dns","level":"super","format":"single","q":"Que traduit en général un code de retour SERVFAIL ?","a":["Le nom demandé n'existe pas dans la zone interrogée (réponse faisant autorité)","L'enregistrement existe mais son type est différent de celui demandé, la réponse est vide","Le serveur n'a pas pu traiter la requête (panne côté serveur ou échec de validation, par exemple DNSSEC)","Le client n'a pas le droit d'interroger ce serveur, qui refuse la requête par politique"],"g":2,"e":"SERVFAIL indique un échec côté serveur : zone illisible, serveur amont injoignable ou signature DNSSEC invalide. Un type absent donne une réponse vide (NOERROR) et un nom inexistant donne NXDOMAIN."},
  {"theme":"dns","level":"super","format":"single","q":"Quel est le principe d'un empoisonnement de cache DNS ?","a":["Saturer le serveur DNS de requêtes parasites afin de le rendre indisponible","Faire accepter de fausses réponses à un résolveur pour rediriger les utilisateurs vers l'attaquant","Chiffrer le contenu des zones d'un serveur pour réclamer ensuite une rançon","Voler la clé privée de la zone afin de signer soi-même de fausses réponses"],"g":1,"e":"Si le résolveur garde une fausse réponse en cache, tous ses utilisateurs sont redirigés. Le hasard des ports sources et des identifiants, ainsi que DNSSEC, compliquent l'attaque."},
  {"theme":"dns","level":"super","format":"single","q":"Que garantit DNSSEC ?","a":["L'anonymat de l'utilisateur, dont l'adresse IP est masquée","La confidentialité des requêtes, chiffrées de bout en bout","Une résolution plus rapide grâce à un cache dédié aux zones signées","L'authenticité et l'intégrité des réponses DNS grâce à des signatures"],"g":3,"e":"DNSSEC signe les enregistrements : on peut vérifier qu'ils viennent bien de la zone et n'ont pas été modifiés. Il ne chiffre rien : c'est le rôle de DoT et DoH."},
  {"theme":"dns","level":"super","format":"single","q":"Quel est l'intérêt principal du DNS sur HTTPS (DoH) ou sur TLS (DoT) ?","a":["Chiffrer les requêtes entre le client et le résolveur","Accélérer la résolution grâce à un cache partagé","Remplacer les enregistrements MX par un service web","Signer les zones pour prouver leur authenticité"],"g":0,"e":"DoH et DoT empêchent un observateur du réseau de lire ou modifier les requêtes. En entreprise, ils peuvent contourner le filtrage DNS si on ne les encadre pas."},
  {"theme":"dns","level":"super","format":"single","q":"Avant de migrer un site vers un nouveau serveur, quelle précaution limite la durée de la bascule ?","a":["Baisser le TTL de l'enregistrement quelques jours à l'avance","Augmenter le TTL au maximum quelques jours à l'avance","Vider le cache de chaque navigateur avant la bascule","Supprimer l'enregistrement la veille puis le recréer"],"g":0,"e":"Avec un TTL court (par exemple 300 secondes), les caches se renouvellent vite après le changement d'adresse. On le remonte ensuite pour réduire la charge."},
  {"theme":"dns","level":"super","format":"single","q":"Où publie-t-on la politique DMARC du domaine exemple.fr ?","a":["Dans un enregistrement SRV au nom exemple.fr","Dans un enregistrement CNAME pour mail.exemple.fr","Dans un enregistrement TXT au nom _dmarc.exemple.fr","Dans un enregistrement MX au nom dmarc.exemple.fr"],"g":2,"e":"DMARC se publie en TXT sur le sous-domaine _dmarc. SPF se publie en TXT sur le domaine lui-même et DKIM sous selecteur._domainkey."},
  {"theme":"dns","level":"super","format":"single","q":"Comment un domaine parent confie-t-il la gestion d'un sous-domaine (par exemple lab.exemple.fr) à d'autres serveurs ?","a":["Par un redirecteur conditionnel configuré sur chaque résolveur","Par une délégation : des enregistrements NS dans la zone parente","Par un enregistrement CNAME pointant vers le sous-domaine","Par un transfert de zone vers les serveurs du sous-domaine"],"g":1,"e":"La délégation consiste à publier dans la zone parente des NS qui désignent les serveurs de la zone enfant. Les résolveurs suivent ce renvoi."},
  {"theme":"dns","level":"super","format":"single","q":"Quel est l'effet de baisser le TTL d'un enregistrement très consulté de 86400 à 300 secondes ?","a":["Le serveur ne reçoit plus aucune requête, car tout est servi par les caches","Les réponses des caches deviennent chiffrées entre le serveur et les résolveurs","L'enregistrement n'est plus du tout mis en cache, ni par les résolveurs ni par les navigateurs","Les caches se renouvellent plus vite, mais le serveur reçoit davantage de requêtes"],"g":3,"e":"Un TTL court accélère la propagation des changements, au prix de plus de trafic vers les serveurs faisant autorité. C'est un compromis à ajuster."},
  {"theme":"dns","level":"super","format":"tf","q":"Un CNAME peut coexister avec un enregistrement MX sur le même nom.","a":["Vrai","Faux"],"g":1,"e":"Faux : un CNAME doit être le seul enregistrement du nom. Un MX sur le même nom provoque des comportements imprévisibles, d'où l'impossibilité d'un CNAME à l'apex d'un domaine qui reçoit du courrier."},
  {"theme":"dns","level":"super","format":"tf","q":"Quand une réponse DNS en UDP est trop grande, le client peut la redemander en TCP.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le serveur signale la troncature (bit TC) et le client recommence en TCP. C'est une des raisons pour lesquelles le port 53 TCP doit rester ouvert."},
  {"theme":"dns","level":"super","format":"multi","q":"Quelles mesures réduisent le risque d'attaque par amplification DNS ? (plusieurs réponses)","a":["Limiter le débit des réponses identiques (response rate limiting)","Interdire la récursion aux adresses extérieures","Augmenter le TTL de toutes les zones","Remplacer tous les enregistrements A par des CNAME"],"g":[0,1],"e":"L'amplification abuse de résolveurs ouverts : l'attaquant usurpe l'adresse de la victime et obtient de grosses réponses. On ferme la récursion et on limite le débit."},
  {"theme":"dns","level":"super","format":"multi","q":"Quels usages courants des enregistrements TXT existent ? (plusieurs réponses)","a":["Publier l'adresse IPv6 du site web","Prouver la propriété d'un domaine à un service en ligne","Publier une règle SPF","Publier une politique DMARC"],"g":[1,2,3],"e":"Les TXT servent de support à SPF, DKIM, DMARC et aux vérifications de propriété demandées par Microsoft 365 ou d'autres services. L'adresse IPv6 va dans un AAAA."},
  {"theme":"dns","level":"super","format":"order","q":"Remets dans l'ordre une migration de site avec un minimum de coupure :","items":["Baisser le TTL de l'enregistrement A plusieurs jours avant","Mettre le nouveau serveur en service et le tester directement par son IP","Modifier l'enregistrement A pour pointer vers la nouvelle adresse","Surveiller puis remonter le TTL quand tout est stable"],"e":"Le TTL court est la clé : il faut le baisser avant le changement, puis vérifier que tout fonctionne avant de le remonter."},
  {"theme":"dns","level":"super","format":"input","q":"Quelle commande dig suit la résolution depuis les serveurs racine, étape par étape ?","placeholder":"Commande","answers":["dig +trace","+trace","dig +trace exemple.fr","dig exemple.fr +trace"],"e":"dig +trace exemple.fr montre chaque délégation : racine, TLD puis serveurs de la zone. Utile pour repérer une délégation cassée."},
  {"theme":"dns","level":"super","format":"input","q":"Quel code de retour DNS indique que le serveur refuse de répondre à une requête ? (en majuscules)","placeholder":"Code de retour","answers":["REFUSED"],"e":"REFUSED apparaît quand le serveur n'accepte pas la requête : récursion non autorisée pour ce client, transfert de zone interdit, etc."},
  {"theme":"dns","level":"super","format":"input","q":"Comment s'appelle le champ de l'enregistrement SOA qui s'incrémente à chaque modification de la zone ?","placeholder":"Nom du champ","answers":["serial","numéro de série","numero de serie","serial number"],"e":"Le numéro de série (serial) permet aux serveurs secondaires de savoir si la zone a changé : ils demandent un transfert quand il augmente."},
  {"theme":"dns","level":"legende","format":"single","q":"Quel indice dans les journaux DNS évoque un tunnel DNS ou une exfiltration de données ?","a":["Un poste interroge fréquemment l'enregistrement A de l'intranet et de quelques serveurs de fichiers","Un poste obtient quelques NXDOMAIN à cause de fautes de frappe dans les noms saisis","Le serveur reçoit des requêtes TCP pour un transfert de zone planifié vers son secondaire","Un poste envoie de nombreuses requêtes TXT vers des sous-domaines longs et aléatoires d'un même domaine"],"g":3,"e":"Un tunnel encode des données dans les noms (sous-domaines longs, caractères aléatoires) et les récupère dans les réponses (TXT, NULL). Le volume et l'entropie des noms trahissent l'usage."},
  {"theme":"dns","level":"legende","format":"single","q":"Des centaines de NXDOMAIN en quelques minutes pour des noms aléatoires (xk3jd9.com) venant d'un même poste évoquent surtout…","a":["Une zone DNS inverse mal configurée qui multiplie les requêtes PTR sans réponse","Un logiciel malveillant qui génère des domaines (DGA) pour retrouver son serveur de commande","Un transfert de zone non autorisé que tenterait un attaquant sur le DNS interne depuis ce poste","Une panne du serveur DHCP qui empêche les postes d'obtenir leur configuration"],"g":1,"e":"Un DGA (Domain Generation Algorithm) produit chaque jour des milliers de noms ; seuls quelques-uns sont enregistrés par l'attaquant. Le poste essaie les noms et reçoit surtout des NXDOMAIN."},
  {"theme":"dns","level":"legende","format":"single","q":"Un CNAME pointe vers un service cloud supprimé (par exemple app-xyz.azurewebsites.net). Quel est le risque ?","a":["Aucun risque, un CNAME orphelin est simplement ignoré par les résolveurs","Un empoisonnement du cache du résolveur interne, qui renverrait de fausses réponses aux postes du domaine","Un attaquant peut recréer la ressource sous ce nom et prendre le contrôle du sous-domaine","L'expiration du certificat racine du domaine, ce qui bloque les connexions"],"g":2,"e":"Le sous-domaine continue de pointer vers un nom libre. Si un tiers le réserve, il sert du contenu sous votre domaine (phishing, vol de cookies). Il faut supprimer les enregistrements orphelins."},
  {"theme":"dns","level":"legende","format":"single","q":"À quoi sert une zone RPZ (Response Policy Zone) sur un résolveur ?","a":["À modifier ou bloquer les réponses pour certains domaines (filtrage, sinkhole)","À répliquer les zones entre deux sites distants à intervalle régulier","À signer les zones avec DNSSEC et à publier les enregistrements DS","À chiffrer le trafic entre le résolveur et les clients internes"],"g":0,"e":"Une RPZ applique une politique : domaines malveillants renvoyés vers une adresse de sinkhole ou en NXDOMAIN. C'est un outil de blocage DNS pour les équipes de sécurité."},
  {"theme":"dns","level":"legende","format":"single","q":"Pourquoi faut-il un « glue record » pour ns1.exemple.fr quand ce serveur est celui de la zone exemple.fr ?","a":["Pour éviter une dépendance circulaire : la zone parente fournit l'adresse IP du serveur de noms","Pour signer les enregistrements NS de la zone parente avec la clé du registre du domaine","Pour réduire le TTL des enregistrements A du serveur et accélérer leur propagation","Pour chiffrer le transfert de zone entre le serveur principal et ses secondaires"],"g":0,"e":"Sans l'adresse de ns1 fournie par .fr, il faudrait résoudre ns1.exemple.fr… en interrogeant ns1.exemple.fr. Le glue casse la boucle."},
  {"theme":"dns","level":"legende","format":"single","q":"Que vise une attaque par DNS rebinding ?","a":["Casser la signature DNSSEC d'une zone en forçant les résolveurs à accepter de fausses réponses non validées","Faire résoudre un nom public vers une adresse interne pour contourner la politique de même origine du navigateur","Rediriger les mails d'un domaine vers un serveur MX frauduleux contrôlé par l'attaquant","Saturer le cache d'un résolveur avec des milliers de noms aléatoires pour le rendre inutilisable"],"g":1,"e":"L'attaquant répond d'abord avec son IP, puis, avec un TTL très court, avec une IP interne (192.168.x.x). Le navigateur croit rester sur le même site et laisse le script parler aux équipements internes."},
  {"theme":"dns","level":"legende","format":"single","q":"À quoi sert un enregistrement CAA ?","a":["À publier la clé DKIM utilisée pour signer les messages du domaine","À interdire le transfert de zone vers des serveurs non autorisés","À déclarer quels serveurs de messagerie peuvent envoyer du courrier pour le domaine","À indiquer quelles autorités de certification peuvent émettre des certificats du domaine"],"g":3,"e":"Avant d'émettre un certificat, une autorité de certification doit consulter le CAA. Restreindre les autorités autorisées limite les émissions frauduleuses."},
  {"theme":"dns","level":"legende","format":"single","q":"Dans DNSSEC, que contient l'enregistrement DS publié dans la zone parente ?","a":["La clé privée de la zone enfant, utilisée pour signer ses propres enregistrements","Le nombre maximal de requêtes par seconde autorisé pour la zone enfant","L'empreinte (hash) de la clé de signature de la zone enfant, qui crée la chaîne de confiance","La liste des serveurs de noms de la zone enfant et leurs adresses IP"],"g":2,"e":"Le DS relie la zone enfant à son parent : le parent signe l'empreinte de la clé de l'enfant, et ainsi de suite jusqu'à la racine. La clé privée ne quitte jamais la zone."},
  {"theme":"dns","level":"legende","format":"single","q":"Quelle valeur fixe la durée pendant laquelle une réponse NXDOMAIN peut être mise en cache ?","a":["Le TTL de l'enregistrement NS le plus long de la zone interrogée","La valeur Refresh du SOA, qui cadence les copies vers les secondaires","Le TTL négatif, déterminé par le champ minimum de l'enregistrement SOA","Le TTL du CNAME le plus long de la zone, quel que soit le type interrogé"],"g":2,"e":"Le cache négatif (RFC 2308) mémorise l'absence d'un nom. Sa durée est tirée du SOA de la zone. Un nom créé juste après une requête peut donc rester « inexistant » un moment pour certains résolveurs."},
  {"theme":"dns","level":"legende","format":"single","q":"Comment limiter les contournements du filtrage DNS d'entreprise par DoH dans les navigateurs ?","a":["Imposer par stratégie le résolveur interne ou désactiver DoH dans les navigateurs, et bloquer les résolveurs DoH publics connus","Fermer uniquement le port 53 en UDP et en TCP sur le pare-feu, puisque DoH passe par ce port","Passer tous les postes en IPv6 pour que les requêtes DNS ne soient plus visibles du pare-feu","Augmenter le TTL des enregistrements internes pour que les postes n'interrogent plus de résolveur externe"],"g":0,"e":"DoH passe par le port 443 comme le web ordinaire : bloquer le port 53 ne suffit pas. On pilote le navigateur par GPO ou MDM, et on filtre les points d'accès DoH connus."},
  {"theme":"dns","level":"legende","format":"tf","q":"Un enregistrement NS doit toujours contenir une adresse IP.","a":["Vrai","Faux"],"g":1,"e":"Faux : un NS contient un nom de serveur, jamais une adresse. C'est un enregistrement A ou AAAA (ou un glue) qui donne l'adresse de ce serveur."},
  {"theme":"dns","level":"legende","format":"multi","q":"Quels éléments aident à repérer un tunnel DNS ? (plusieurs réponses)","a":["Des requêtes A régulières vers le serveur de mises à jour interne","Un volume anormal de requêtes TXT ou NULL vers un même domaine","Des réponses courtes avec un TTL de 3600 pour www","Des noms de domaine très longs avec des sous-domaines à l'allure aléatoire"],"g":[1,3],"e":"Un tunnel se reconnaît à l'entropie des noms, à leur longueur et au volume inhabituel de types d'enregistrements peu courants comme TXT et NULL."},
  {"theme":"dns","level":"legende","format":"multi","q":"Quelles mesures réduisent le risque de subdomain takeover ? (plusieurs réponses)","a":["Supprimer les enregistrements DNS quand on supprime la ressource cloud associée","Chiffrer les requêtes DNS avec DoH","Auditer régulièrement les CNAME qui pointent vers des services externes","Mettre un TTL de 86400 sur tous les CNAME"],"g":[0,2],"e":"Le risque vient d'enregistrements orphelins : la bonne pratique est de les supprimer en même temps que la ressource et d'inventorier ceux qui pointent vers l'extérieur."},
  {"theme":"dns","level":"legende","format":"multi","q":"Quels enregistrements interviennent dans la validation DNSSEC ? (plusieurs réponses)","a":["SRV","RRSIG","DNSKEY","CAA"],"g":[1,2],"e":"RRSIG contient la signature d'un jeu d'enregistrements et DNSKEY la clé publique pour la vérifier. S'y ajoutent DS (chaîne de confiance) et NSEC ou NSEC3 (preuve d'inexistence)."},
  {"theme":"dns","level":"legende","format":"order","q":"Remets dans l'ordre la chaîne de confiance DNSSEC, de la plus haute à la plus basse :","items":["L'ancre de confiance : la clé publique de la zone racine","La racine publie l'enregistrement DS du TLD (.fr)","Le TLD publie l'enregistrement DS de exemple.fr","La zone exemple.fr signe ses enregistrements (RRSIG)"],"e":"Le résolveur part de la clé de la racine, qu'il connaît d'avance, puis vérifie chaque DS jusqu'à la signature de l'enregistrement demandé."},
  {"theme":"dns","level":"legende","format":"input","q":"Quelle commande vérifie la santé DNS d'un contrôleur de domaine Active Directory ?","placeholder":"Commande","answers":["dcdiag /test:dns","dcdiag /test:dns /v","dcdiag /test:dns /e /v","dcdiag /v /test:dns"],"e":"dcdiag /test:dns contrôle l'enregistrement des SRV, la délégation, la résolution et la réplication DNS d'un contrôleur de domaine."},
  {"theme":"dns","level":"legende","format":"input","q":"Quel sous-domaine spécial d'Active Directory contient les enregistrements SRV de localisation des contrôleurs de domaine ? (avec le tiret bas)","placeholder":"Nom du sous-domaine","answers":["_msdcs","_msdcs.","msdcs"],"e":"Le préfixe _msdcs regroupe les services propres aux contrôleurs de domaine (_ldap._tcp.dc._msdcs.domaine). Sa suppression ou sa corruption empêche les ouvertures de session."},
  {"theme":"dns","level":"legende","format":"input","q":"Quel type d'enregistrement DNSSEC contient la signature d'un jeu d'enregistrements ? (cinq lettres)","placeholder":"Type d'enregistrement","answers":["RRSIG"],"e":"RRSIG (Resource Record Signature) accompagne chaque jeu d'enregistrements signé. Le résolveur le vérifie avec la clé publique publiée dans DNSKEY."},
  {"theme":"dns","level":"legende","format":"input","q":"Quel est le numéro de port utilisé par le DNS sur TLS (DoT) ?","placeholder":"Numéro de port","answers":["853","tcp 853","tcp/853","port 853","853/tcp","port 853 tcp","tcp port 853"],"e":"DoT utilise le port 853 en TCP, ce qui permet de le repérer et de le bloquer, contrairement à DoH qui se cache dans le trafic HTTPS sur le port 443."},
  {"theme":"dns","level":"legende","format":"input","q":"Quel nom de domaine spécial sert à la résolution inverse des adresses IPv4 ?","placeholder":"Nom de domaine","answers":["in-addr.arpa","in-addr.arpa."],"e":"Une adresse 192.168.1.10 se retrouve dans la zone 1.168.192.in-addr.arpa. Pour IPv6, on utilise ip6.arpa."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Quelle situation dégrade le plus la qualité d'un appel Teams ?","a":["Un nom d'équipe trop long, dépassant la limite d'affichage","Un fond d'écran animé très lourd, installé sur le poste","Une forte perte de paquets ou une gigue élevée sur la liaison","Une barre des tâches très personnalisée, chargée d'extensions"],"g":2,"e":"Pour l'audio et la vidéo en temps réel, ce qui compte est la qualité du réseau : paquets perdus, délais irréguliers (gigue), latence. L'apparence du poste n'y change rien."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Pour une réunion Teams importante, quelle connexion est la plus fiable ?","a":["Le Wi-Fi 2,4 GHz partagé avec les voisins","Un point d'accès public ouvert","Un partage de connexion depuis un téléphone en veille","Un câble Ethernet"],"g":3,"e":"Le câble offre une latence stable et sans interférences. En Wi-Fi, le 5 GHz est préférable au 2,4 GHz, souvent encombré."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Que mesure la latence d'une liaison ?","a":["Le nombre de paquets perdus pendant la transmission","Le temps de transit d'un paquet entre deux points","Le volume de données transféré par seconde","La variation du délai d'arrivée des paquets"],"g":1,"e":"La latence s'exprime en millisecondes. Le volume par seconde est le débit, la variation du délai est la gigue et les paquets perdus forment le taux de perte."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Que mesure la gigue (jitter) ?","a":["La variation du délai d'arrivée des paquets","La distance entre le poste et le serveur","Le débit maximal théorique de la ligne","Le nombre d'utilisateurs connectés en même temps"],"g":0,"e":"Une gigue élevée fait arriver les paquets de voix à intervalles irréguliers : le son est haché ou robotique, même si la moyenne du délai est correcte."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Un test de débit affiche un excellent résultat, mais les appels Teams sont hachés. Pourquoi ?","a":["Les tests de débit ne sont valables qu'en Wi-Fi et faussent le résultat sur une liaison filaire","Les appels Teams utilisent uniquement le port 80, que le test de débit ne sollicite pas","Teams exige un débit supérieur à 1 Gbit/s par utilisateur, ce qu'un test ponctuel ne vérifie pas","Le débit ne mesure ni la perte de paquets, ni la latence, ni la gigue, essentielles pour l'audio et la vidéo"],"g":3,"e":"Un appel Teams consomme peu de débit, mais il est très sensible à la qualité de la liaison. Un test de débit seul ne suffit donc pas pour diagnostiquer."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Quel port TCP est utilisé par la plupart des échanges de Microsoft 365 ?","a":["Le port 443 (HTTPS)","Le port 3389 (RDP)","Le port 110 (POP3)","Le port 21 (FTP) en clair"],"g":0,"e":"Microsoft 365 repose sur HTTPS. Autoriser le port 443 vers les adresses Microsoft est donc la base de la configuration d'un pare-feu."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Quel outil Microsoft teste la connectivité réseau d'un poste vers Microsoft 365 ?","a":["Le Planificateur de tâches du système Windows","L'Observateur d'événements de Windows","Le test de connectivité réseau Microsoft 365","Le Gestionnaire de périphériques de Windows"],"g":2,"e":"Le test de connectivité réseau Microsoft 365 (connectivity.office.com) mesure latence, sortie Internet, proxy et DNS depuis le poste testé."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Qu'est-ce qui peut empêcher Teams de se connecter dans une entreprise ?","a":["Un poste dont la langue d'affichage Windows est l'anglais","Un pare-feu ou un proxy qui bloque les adresses de Microsoft 365","Un écran de taille inférieure à quinze pouces sur le poste","Un service DHCP configuré avec une durée de bail de huit jours"],"g":1,"e":"Si les flux vers Microsoft ne sont pas autorisés (443, UDP 3478 à 3481, noms de domaine…), Teams ne se connecte pas ou fonctionne en mode dégradé."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Quel enregistrement DNS faut-il modifier pour que le courrier d'un domaine arrive dans Exchange Online ?","a":["L'enregistrement NS du registre","L'enregistrement MX","L'enregistrement PTR","L'enregistrement A du site web"],"g":1,"e":"L'enregistrement MX du domaine doit pointer vers Exchange Online, sous la forme domaine-fr.mail.protection.outlook.com."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Un utilisateur en télétravail via VPN trouve Teams lent, alors que tout va bien sans VPN. Quelle explication est la plus simple ?","a":["Le VPN supprime la licence Teams de l'utilisateur à chaque connexion","Le DNS de Microsoft refuse les requêtes venant des adresses IP du VPN","Tout le trafic passe par le tunnel VPN jusqu'au siège, puis repart vers Microsoft 365","Teams ne fonctionne pas avec le chiffrement des tunnels VPN"],"g":2,"e":"Ce détour allonge le trajet et sature le VPN. D'où l'intérêt du tunnel partagé (split tunneling) pour les flux Microsoft 365."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Pourquoi Microsoft publie-t-il la liste de ses adresses et noms de domaine (points de terminaison) ?","a":["Pour que les administrateurs autorisent ces flux dans leur pare-feu et leur proxy","Pour permettre aux entreprises de bloquer Teams sur leur réseau","Pour les revendre aux fournisseurs d'accès et aux opérateurs","Pour informer les utilisateurs des pannes de service en cours"],"g":0,"e":"Cette liste est publiée et mise à jour régulièrement. Elle permet de ne laisser passer que ce qui est nécessaire, sans ouvrir tout Internet."},
  {"theme":"reseau365","level":"recrue","format":"single","q":"Quel symptôme évoque un problème de connexion à Exchange Online dans Outlook ?","a":["Un bandeau « Mode sombre activé » en haut de la fenêtre Outlook","Des mails reçus qui s'affichent sans leurs pièces jointes ni leurs images intégrées","Un calendrier dont les couleurs de catégories changent","Un bandeau « Déconnecté » ou « Tentative de connexion » en bas de la fenêtre"],"g":3,"e":"Outlook affiche l'état de sa connexion à la boîte aux lettres. Un état déconnecté pointe vers le réseau, l'authentification ou la configuration, pas vers l'affichage."},
  {"theme":"reseau365","level":"recrue","format":"tf","q":"Un test de débit élevé garantit à lui seul de bons appels Teams.","a":["Vrai","Faux"],"g":1,"e":"Faux : la perte de paquets, la latence et la gigue pèsent davantage sur la voix et la vidéo que le débit."},
  {"theme":"reseau365","level":"recrue","format":"tf","q":"Le Wi-Fi 5 GHz porte moins loin que le 2,4 GHz, mais il subit en général moins d'interférences.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le 5 GHz traverse moins bien les murs mais offre plus de canaux et moins d'encombrement, ce qui profite aux appels en temps réel."},
  {"theme":"reseau365","level":"recrue","format":"tf","q":"Quand on est au bureau, Microsoft 365 n'utilise pas Internet.","a":["Vrai","Faux"],"g":1,"e":"Faux : Microsoft 365 est un service dans le cloud. Même au bureau, les flux passent par la sortie Internet de l'entreprise."},
  {"theme":"reseau365","level":"recrue","format":"multi","q":"Quels éléments influencent la qualité d'un appel Teams ? (plusieurs réponses)","a":["La gigue","Le thème de couleur de Teams","La perte de paquets","Le nombre de canaux de l'équipe"],"g":[0,2],"e":"Perte de paquets, gigue et latence sont les trois indicateurs réseau clés d'un appel. L'apparence de l'application n'a aucun effet."},
  {"theme":"reseau365","level":"recrue","format":"multi","q":"Quelles causes peuvent empêcher Outlook de se connecter à Exchange Online ? (plusieurs réponses)","a":["Un fond d'écran modifié","Une imprimante hors ligne","Un enregistrement autodiscover mal configuré","Une coupure de la connexion Internet"],"g":[2,3],"e":"Sans Internet, ou sans la découverte automatique des paramètres, Outlook ne peut pas joindre la boîte aux lettres. Le reste n'a aucun lien."},
  {"theme":"reseau365","level":"recrue","format":"order","q":"Remets dans l'ordre un diagnostic simple de lenteur sur Teams :","items":["Vérifier que le poste a bien accès à Internet","Tester si le problème existe aussi hors VPN ou sur un autre réseau","Mesurer la perte de paquets, la latence et la gigue","Contrôler les règles du pare-feu et du proxy"],"e":"On part du plus simple (accès Internet), on isole la cause (VPN, réseau local), on mesure, puis on vérifie la configuration des équipements."},
  {"theme":"reseau365","level":"recrue","format":"input","q":"Quel numéro de port TCP utilise HTTPS ?","placeholder":"Numéro de port","answers":["443","tcp 443","tcp/443"],"e":"HTTPS écoute sur le port 443. C'est celui qu'il faut autoriser en priorité vers Microsoft 365."},
  {"theme":"reseau365","level":"recrue","format":"input","q":"Quel mot anglais désigne la variation du délai d'arrivée des paquets ?","placeholder":"Un mot","answers":["jitter","gigue"],"e":"La gigue (jitter) est l'irrégularité des délais d'arrivée. Elle dégrade la voix même si la latence moyenne est bonne."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quelle catégorie de points de terminaison Microsoft 365 regroupe les flux sensibles à la latence, à faire sortir directement sans proxy ni inspection ?","a":["Traiter par défaut (Default)","Autoriser (Allow)","Bloquer (Block)","Optimiser (Optimize)"],"g":3,"e":"Microsoft classe ses points de terminaison en Optimiser, Autoriser et Par défaut. « Optimiser » regroupe peu d'adresses mais la plus grande part du volume et des flux sensibles : Teams, Exchange, SharePoint."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Où trouve-t-on la liste officielle et à jour des adresses et URL de Microsoft 365 ?","a":["Dans le service web des points de terminaison (endpoints.office.com)","Sur le site web du fournisseur d'accès à Internet de l'entreprise","Dans le journal des événements Windows des postes clients","Dans le fichier hosts du serveur Exchange, mis à jour par Microsoft"],"g":0,"e":"Microsoft publie la liste sur une page de documentation et via un service web au format JSON, mis à jour par numéro de version, ce qui permet de l'automatiser."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quelle plage de ports UDP Teams utilise-t-il pour ses flux audio et vidéo vers Microsoft ?","a":["UDP 5060 à 5061 (SIP)","UDP 8080 à 8081","UDP 3478 à 3481","UDP 1812 à 1813"],"g":2,"e":"Teams envoie ses médias en UDP vers les relais Microsoft sur les ports 3478 à 3481. Le 5060 est celui de SIP, le 1812 celui de RADIUS."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Que se passe-t-il quand l'UDP est bloqué pour Teams ?","a":["Teams ne démarre plus du tout tant que l'UDP reste bloqué sur le réseau","Teams bascule sur TCP 443, souvent avec une qualité audio et vidéo dégradée","Teams ouvre automatiquement un tunnel VPN vers le siège pour contourner","Les flux sont chiffrés avec une clé plus courte pour limiter la charge"],"g":1,"e":"Le TCP, qui retransmet les paquets perdus, ajoute de la latence aux flux temps réel. Autoriser l'UDP est donc recommandé."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Pourquoi Microsoft déconseille-t-il de faire passer les flux média de Teams par un proxy ?","a":["Teams interdit tout intermédiaire réseau dans ses conditions d'utilisation","Les proxys n'acceptent pas le trafic chiffré sur le port 443","Le proxy ajoute de la latence et de la gigue à un trafic temps réel","Le proxy supprime les fichiers partagés dans les conversations"],"g":2,"e":"Les médias sont envoyés directement aux relais Microsoft. Un proxy ou une inspection n'apporte rien de plus pour ce trafic déjà chiffré et sensible aux délais."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quel seuil de perte de paquets (mesurée sur 15 secondes) Microsoft recommande-t-il de ne pas dépasser pour Teams ?","a":["1 %","10 %","20 %","5 %"],"g":0,"e":"Microsoft recommande moins de 1 % de perte sur 15 secondes, une gigue inférieure à 30 ms et une latence aller simple inférieure à 100 ms."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Que contient en général l'enregistrement SPF d'un domaine qui envoie ses mails via Exchange Online ?","a":["include:spf.mail.office365.com","include:spf.protection.outlook.com","ip4:10.0.0.0/8 ip4:192.168.0.0/16","redirect:spf.protection.outlook.net"],"g":1,"e":"v=spf1 include:spf.protection.outlook.com -all autorise les serveurs Microsoft à envoyer pour le domaine. On y ajoute les autres expéditeurs légitimes."},
  {"theme":"reseau365","level":"hero","format":"single","q":"À quoi sert l'enregistrement CNAME autodiscover qui pointe vers autodiscover.outlook.com ?","a":["À déclarer aux serveurs distants le serveur SMTP sortant du domaine","À activer l'authentification multifacteur pour les boîtes aux lettres","À rediriger le site web de l'entreprise vers Outlook sur le web","À permettre à Outlook de configurer automatiquement la boîte aux lettres"],"g":3,"e":"La découverte automatique fournit à Outlook l'adresse du serveur, le profil et les services disponibles à partir de l'adresse mail saisie."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quelle version minimale du protocole TLS Microsoft 365 exige-t-il ?","a":["TLS 1.1","SSL 3.0 (SSLv3)","TLS 1.2","TLS 1.0"],"g":2,"e":"Les versions antérieures à TLS 1.2 sont désactivées sur les services Microsoft 365. Les anciens systèmes ou appareils qui ne gèrent pas TLS 1.2 ne peuvent plus s'y connecter."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quel outil du centre d'administration Teams aide à estimer la bande passante nécessaire sur un site ?","a":["Le rapport d'utilisation d'Exchange Online","Le tableau de bord des licences attribuées","Le journal d'audit du portail Purview","Le planificateur de réseau (Network planner)"],"g":3,"e":"Le planificateur de réseau estime la bande passante requise selon le nombre d'utilisateurs, les types d'appels et les réunions prévus par site."},
  {"theme":"reseau365","level":"hero","format":"single","q":"Quel outil permet d'analyser la qualité des appels Teams de toute l'entreprise (pertes, gigue, sites, types de réseau) ?","a":["Le tableau de bord de qualité des appels (CQD)","Le centre de messages de l'administration","Le journal d'activité des connexions Entra ID","Le Secure Score du portail Microsoft Defender"],"g":0,"e":"Le CQD (Call Quality Dashboard) agrège les données d'appels par bâtiment, sous-réseau ou type de connexion et révèle les zones problématiques."},
  {"theme":"reseau365","level":"hero","format":"tf","q":"Il est recommandé que chaque site accède à Microsoft 365 par la sortie Internet la plus proche, plutôt que par un proxy central éloigné.","a":["Vrai","Faux"],"g":0,"e":"Vrai : la sortie locale évite les détours et réduit la latence. C'est l'un des principes de connectivité de Microsoft 365."},
  {"theme":"reseau365","level":"hero","format":"tf","q":"Les points de terminaison de la catégorie « Optimiser » représentent la majorité des URL de la liste.","a":["Vrai","Faux"],"g":1,"e":"Faux : ils sont très peu nombreux (quelques URL et plages), mais portent la plus grande part du volume et des flux critiques."},
  {"theme":"reseau365","level":"hero","format":"multi","q":"Quels services figurent dans la catégorie « Optimiser » ? (plusieurs réponses)","a":["Les flux Teams (appels et réunions)","Les flux SharePoint Online et OneDrive","Les mises à jour de pilotes d'imprimante","Les flux Exchange Online"],"g":[0,1,3],"e":"Optimiser couvre Exchange Online, SharePoint Online (dont OneDrive) et les médias Teams. Les mises à jour de pilotes n'en font pas partie."},
  {"theme":"reseau365","level":"hero","format":"multi","q":"Quelles mesures améliorent l'accès à Microsoft 365 depuis un site distant ? (plusieurs réponses)","a":["Un résolveur DNS proche des utilisateurs","Faire passer tout le trafic par le siège","Une sortie Internet locale","Désactiver le cache DNS des postes"],"g":[0,2],"e":"Une sortie locale et un DNS proche dirigent les clients vers un point d'entrée Microsoft proche. Le détour par le siège fait l'inverse."},
  {"theme":"reseau365","level":"hero","format":"order","q":"Remets dans l'ordre les principes de connectivité Microsoft 365 :","items":["Identifier et distinguer le trafic Microsoft 365","Sortir les connexions localement","Éviter les détours réseau","Étudier le contournement des proxys et de l'inspection pour les flux critiques"],"e":"Microsoft recommande d'abord de reconnaître le trafic, puis de le faire sortir au plus près, sans détour, et enfin d'alléger les contrôles sur les flux les plus sensibles."},
  {"theme":"reseau365","level":"hero","format":"input","q":"Quel protocole de transport les flux média de Teams utilisent-ils en priorité ? (TCP ou UDP)","placeholder":"TCP ou UDP","answers":["UDP"],"e":"Les médias passent en UDP, sensible aux pertes mais rapide. Le TCP 443 ne sert que de repli si l'UDP est bloqué."},
  {"theme":"reseau365","level":"hero","format":"input","q":"Quel sous-domaine DNS Outlook interroge-t-il pour la configuration automatique de la boîte aux lettres ?","placeholder":"Nom du sous-domaine","answers":["autodiscover","autodiscover.domaine"],"e":"autodiscover.domaine.fr, en CNAME vers autodiscover.outlook.com pour Exchange Online, permet à Outlook de trouver ses paramètres."},
  {"theme":"reseau365","level":"hero","format":"input","q":"Quelle cmdlet PowerShell teste une connexion TCP, par exemple vers outlook.office365.com sur le port 443 ?","placeholder":"Cmdlet","answers":["Test-NetConnection"],"e":"Test-NetConnection outlook.office365.com -Port 443 indique si la connexion TCP aboutit et affiche la latence de base."},
  {"theme":"reseau365","level":"hero","format":"input","q":"Quel site Microsoft propose le Remote Connectivity Analyzer pour tester Exchange et Microsoft 365 ?","placeholder":"Adresse du site","answers":["testconnectivity.microsoft.com","https://testconnectivity.microsoft.com","remote connectivity analyzer","microsoft remote connectivity analyzer"],"e":"testconnectivity.microsoft.com permet de tester la découverte automatique, la messagerie, la connexion Outlook et d'autres scénarios."},
  {"theme":"reseau365","level":"super","format":"single","q":"Pourquoi le tunnel partagé (split tunneling) améliore-t-il Teams pour les télétravailleurs sous VPN ?","a":["Le tunnel est chiffré avec un algorithme plus rapide, ce qui réduit la latence de bout en bout","Les flux Microsoft 365 critiques sortent directement vers Internet, sans passer par le tunnel","Le VPN est remplacé par un proxy inverse installé dans le datacenter du siège","Tout le trafic est compressé puis chiffré avant d'être envoyé dans le tunnel"],"g":1,"e":"En excluant les points de terminaison Optimiser du tunnel, on évite le détour par le siège et la saturation de la passerelle VPN, tout en gardant le reste du trafic protégé."},
  {"theme":"reseau365","level":"super","format":"single","q":"Quelle valeur DSCP est recommandée pour l'audio de Teams ?","a":["34 (AF41)","18 (AF21)","0 (best effort)","46 (EF)"],"g":3,"e":"Microsoft recommande EF (46) pour l'audio, AF41 (34) pour la vidéo et AF21 (18) pour le partage d'application."},
  {"theme":"reseau365","level":"super","format":"single","q":"Quelle valeur DSCP est recommandée pour la vidéo de Teams ?","a":["34 (AF41)","8 (CS1)","18 (AF21)","46 (EF, voix)"],"g":0,"e":"La vidéo est marquée AF41 (34). L'audio, plus sensible aux délais, reçoit la classe EF (46), prioritaire."},
  {"theme":"reseau365","level":"super","format":"single","q":"Le marquage DSCP d'un flux Teams suffit-il à garantir sa priorité de bout en bout ?","a":["Oui, dès lors que le poste marque lui-même chaque paquet de manière correcte","Oui : Internet applique automatiquement la priorité demandée à tous les flux marqués","Non : les équipements du réseau (commutateurs, routeurs, SD-WAN) doivent respecter le marquage","Non : le DSCP ne concerne que le trafic de messagerie et non les flux de réunion"],"g":2,"e":"Le DSCP n'est qu'une étiquette. Elle n'a d'effet que sur les réseaux qui la respectent, c'est-à-dire en général le réseau de l'entreprise, rarement Internet."},
  {"theme":"reseau365","level":"super","format":"single","q":"Pourquoi l'inspection TLS pose-t-elle problème pour certains flux Microsoft 365 ?","a":["Elle chiffre deux fois les données, ce qui double le débit consommé et impose d'élargir la liaison Internet","Elle supprime les cookies de session des navigateurs, ce qui déconnecte les utilisateurs en permanence","Elle ajoute de la latence et peut casser des applications qui n'acceptent pas le certificat intermédiaire, d'où le contournement pour Optimiser","Elle interdit l'authentification multifacteur et force les utilisateurs à se reconnecter sans cesse"],"g":2,"e":"Le déchiffrement coûte du temps de traitement et certains clients refusent un certificat remplacé. Microsoft recommande d'exclure Optimiser, et si possible Autoriser, de l'inspection."},
  {"theme":"reseau365","level":"super","format":"single","q":"Qu'appelle-t-on un détour (hairpin) pour les flux Microsoft 365 ?","a":["Un trafic qui traverse inutilement le siège ou un datacenter avant d'atteindre Microsoft","Une boucle de câblage entre deux commutateurs qui provoque une tempête de diffusion","Un ping envoyé vers sa propre adresse pour tester la pile réseau du poste","Un VLAN réservé à la voix et au trafic de visioconférence du site"],"g":0,"e":"Un site distant qui passe par le siège pour sortir ajoute des centaines de millisecondes. C'est ce qu'il faut éviter."},
  {"theme":"reseau365","level":"super","format":"single","q":"À quoi sert un fichier PAC dans l'accès à Microsoft 365 ?","a":["À planifier le téléchargement des mises à jour d'Office pour les postes de chaque site distant","À indiquer aux navigateurs quelles destinations passent par le proxy et lesquelles sortent en direct","À distribuer automatiquement les adresses IP et le suffixe DNS aux postes du site","À chiffrer les sauvegardes OneDrive avant leur envoi vers le cloud de Microsoft"],"g":1,"e":"Un fichier de configuration automatique du proxy (PAC) contient une fonction JavaScript qui renvoie « DIRECT » ou l'adresse du proxy selon l'adresse demandée. Microsoft fournit des modèles."},
  {"theme":"reseau365","level":"super","format":"single","q":"Quel avantage un SD-WAN apporte-t-il pour Microsoft 365 ?","a":["Il supprime le besoin de DNS en intégrant la résolution des noms dans l'équipement","Il chiffre automatiquement le contenu des mails avant leur envoi vers Exchange Online","Il remplace les licences Microsoft 365 par un abonnement réseau géré et facturé par l'opérateur télécom","Il identifie le trafic par application et le dirige directement vers Internet depuis chaque site"],"g":3,"e":"Le SD-WAN reconnaît les flux Microsoft 365 et les fait sortir localement, tout en gardant les autres flux sur le réseau d'entreprise selon la politique définie."},
  {"theme":"reseau365","level":"super","format":"single","q":"Que dit la recommandation générale de Microsoft au sujet d'ExpressRoute pour Microsoft 365 ?","a":["Elle est obligatoire dès qu'un site dépasse cent utilisateurs simultanés sur Teams","Elle remplace le pare-feu de l'entreprise et supprime le besoin de proxy","Elle est obligatoire pour qu'un site utilise Teams avec la voix vers le réseau téléphonique public","Elle n'est pas recommandée par défaut : une sortie Internet directe est en général plus performante"],"g":3,"e":"ExpressRoute reste réservé à des cas particuliers et nécessite une validation. Pour la plupart des entreprises, l'accès direct à Internet est plus simple et plus performant."},
  {"theme":"reseau365","level":"super","format":"single","q":"Quel port et quelle méthode un appareil (scanner, application) utilise-t-il pour envoyer du courrier authentifié via Exchange Online ?","a":["TCP 25 vers smtp.office365.com, mot de passe en clair","TCP 143 vers mail.office365.com","TCP 587 avec STARTTLS vers smtp.office365.com","TCP 110 vers outlook.office365.com"],"g":2,"e":"La soumission SMTP authentifiée utilise le port 587 avec STARTTLS. Les ports 110 et 143 sont ceux de POP3 et d'IMAP, qui servent à lire les mails, pas à en envoyer.","maj":{"date":"2026-12-01","precision":"mois","texte":"Microsoft désactivera par défaut l'authentification de base pour SMTP AUTH dans Exchange Online ; il faut passer à OAuth.","source":"Message Center Microsoft 365","url":"https://mc.merill.net/message/MC786329"}},
  {"theme":"reseau365","level":"super","format":"single","q":"Pourquoi résoudre les noms de Microsoft 365 avec un DNS proche des utilisateurs plutôt qu'un DNS centralisé et lointain ?","a":["Cela réduit le coût des licences Microsoft 365 facturées par requête DNS","Le service renvoie un point d'entrée proche de l'endroit d'où provient la requête DNS","Un DNS centralisé bloque la validation des certificats par les navigateurs","Les DNS locaux sont toujours plus sécurisés que les DNS centralisés"],"g":1,"e":"Microsoft choisit le point d'entrée d'après la localisation du résolveur. Un DNS centralisé éloigné envoie donc les utilisateurs vers un point d'entrée éloigné d'eux."},
  {"theme":"reseau365","level":"super","format":"single","q":"Quelle page du centre d'administration Microsoft 365 donne des mesures de connectivité par site ?","a":["La page Connectivité réseau","Le Microsoft Secure Score du tenant","La page État du service","Le journal d'audit Purview"],"g":0,"e":"La page de connectivité réseau mesure, depuis les sites de l'entreprise, la latence et la qualité d'accès, et signale ceux qui s'écartent des bonnes pratiques."},
  {"theme":"reseau365","level":"super","format":"tf","q":"Les points de terminaison de la catégorie « Par défaut » doivent obligatoirement être contournés du proxy.","a":["Vrai","Faux"],"g":1,"e":"Faux : ils représentent le trafic Internet ordinaire et peuvent passer par le proxy. Le contournement s'applique surtout à Optimiser."},
  {"theme":"reseau365","level":"super","format":"tf","q":"Un proxy qui exige une authentification peut empêcher certains clients Microsoft 365 de se connecter.","a":["Vrai","Faux"],"g":0,"e":"Vrai : certains services d'arrière-plan ne savent pas répondre à une demande d'authentification du proxy. D'où l'exemption pour les points de terminaison Microsoft."},
  {"theme":"reseau365","level":"super","format":"multi","q":"Quelles actions limitent l'impact d'un VPN sur Teams ? (plusieurs réponses)","a":["Exclure les points de terminaison Optimiser du tunnel","Mesurer la qualité avec le CQD avant et après le changement","Forcer tout le trafic par le siège","Désactiver l'UDP sur les postes"],"g":[0,1],"e":"Le tunnel partagé réduit la charge du VPN. Mesurer avant et après permet de vérifier le gain. Forcer le trafic au siège ou couper l'UDP aggraverait la situation."},
  {"theme":"reseau365","level":"super","format":"multi","q":"Quels équipements doivent respecter le marquage DSCP pour que le QoS fonctionne ? (plusieurs réponses)","a":["Les imprimantes réseau","Les serveurs DNS","Les routeurs ou équipements SD-WAN","Les commutateurs du réseau local"],"g":[2,3],"e":"La priorité doit être appliquée sur tout le chemin contrôlé par l'entreprise : accès, cœur de réseau et sortie WAN."},
  {"theme":"reseau365","level":"super","format":"order","q":"Remets dans l'ordre la mise en place du QoS pour Teams :","items":["Définir les plages de ports sources pour l'audio, la vidéo et le partage","Activer le marquage dans le centre d'administration Teams et par stratégie sur les postes","Configurer les commutateurs et routeurs pour respecter les valeurs DSCP","Mesurer la qualité avec le CQD avant et après"],"e":"Le marquage s'applique côté poste ; ensuite le réseau doit le respecter. On vérifie enfin le résultat."},
  {"theme":"reseau365","level":"super","format":"input","q":"Quel sigle désigne le fichier qui indique au navigateur comment utiliser un proxy ? (trois lettres)","placeholder":"Sigle","answers":["PAC"],"e":"Le fichier PAC (Proxy Auto-Config) décide pour chaque adresse demandée de passer en direct ou par un proxy."},
  {"theme":"reseau365","level":"super","format":"input","q":"Quel numéro de port TCP utilise la soumission SMTP authentifiée vers Exchange Online ?","placeholder":"Numéro de port","answers":["587","tcp 587","tcp/587"],"e":"Le port 587 avec STARTTLS est celui de la soumission authentifiée. Le port 25 sert aux échanges entre serveurs de messagerie."},
  {"theme":"reseau365","level":"super","format":"input","q":"Quelle latence aller simple maximale (en millisecondes) Microsoft recommande-t-il pour Teams ?","placeholder":"Valeur en ms","answers":["100","100 ms"],"e":"Microsoft recommande moins de 100 ms de latence aller simple, avec une gigue inférieure à 30 ms et moins de 1 % de perte."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Dans une succursale, un proxy cloud inspecte tout le trafic TLS et les appels Teams sont hachés. Quelle action est la plus adaptée ?","a":["Activer l'inspection TLS sur les flux UDP des appels pour les analyser aussi","Exclure du proxy et de l'inspection les points de terminaison Optimiser et Autoriser","Doubler la bande passante de la ligne du site, sans autre changement","Forcer Teams à n'utiliser que le port TCP 80 pour traverser l'inspection du proxy cloud"],"g":1,"e":"Ce trafic est déjà chiffré et sensible aux délais : l'inspecter n'apporte que de la latence. On le fait sortir directement et on garde l'inspection pour le reste."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Pourquoi un pare-feu qui autorise Teams uniquement par noms de domaine peut-il bloquer les médias ?","a":["Les flux média UDP vers les relais Teams se contrôlent surtout par plages d'adresses IP et ports","Le port 443 n'est jamais couvert par une règle fondée sur les noms de domaine","Microsoft interdit l'usage des noms de domaine dans les règles de pare-feu des clients","Teams utilise uniquement IPv6 pour ses flux média, que les noms de domaine ne couvrent pas"],"g":0,"e":"Pour les médias, Microsoft publie des plages d'adresses IP et des ports UDP. Un filtrage par nom ne s'applique qu'au trafic web."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Que risque-t-on en marquant en DSCP 46 tout le trafic vidéo de Teams ?","a":["Chiffrer la vidéo deux fois et doubler le débit utilisé","Désactiver le partage d'écran pendant les réunions","Saturer la file prioritaire prévue pour la voix et dégrader l'audio","Augmenter la latence des résolutions DNS de tout le site, sans effet sur l'audio"],"g":2,"e":"La classe EF doit rester réservée à l'audio, peu gourmand. Y mettre la vidéo, bien plus lourde, peut étouffer la file et nuire à ce qu'on voulait protéger."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Un site relié par satellite (600 ms d'aller-retour) utilise Teams avec un bon débit. Quel symptôme est le plus probable ?","a":["Une impossibilité de résoudre les noms de domaine des serveurs de Teams","Un blocage complet du port 443 vers Microsoft 365","Un conflit d'adresses IP entre deux postes du site","Des délais dans la conversation et des chevauchements de parole"],"g":3,"e":"Une latence élevée n'empêche pas la connexion mais rend la conversation difficile : on se coupe la parole et les réponses arrivent en retard."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Un poste affiche « Connecté, pas d'accès à Internet » alors que le navigateur ouvre des sites. Quel test Windows échoue probablement ?","a":["La validation de l'adresse MAC de la passerelle par le commutateur du site","La détection NCSI vers www.msftconnecttest.com, bloquée par le proxy ou le pare-feu","La résolution du fichier hosts du poste vers l'adresse de la passerelle par défaut","La synchronisation de l'heure avec le contrôleur de domaine, bloquée par le pare-feu"],"g":1,"e":"Windows vérifie l'accès Internet en interrogeant www.msftconnecttest.com. Si ce test est bloqué, l'icône réseau signale un accès limité, et certaines applications Microsoft 365 s'en trouvent perturbées."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Quelle est la différence entre les catégories Optimiser et Autoriser ?","a":["Les deux désignent exactement les mêmes flux, seul le nom varie selon la région du tenant Microsoft 365 utilisé","Optimiser concerne uniquement les flux des serveurs, Autoriser uniquement ceux des postes clients, selon l'origine","Optimiser désigne les flux réservés aux postes d'administration, Autoriser ceux de la messagerie uniquement, sans lien avec la latence","Optimiser : peu de points mais fort volume, très sensibles à la latence. Autoriser : nécessaires mais moins sensibles, un proxy reste possible"],"g":3,"e":"Optimiser est la catégorie à traiter en priorité (sortie directe). Autoriser regroupe des flux utiles dont la sensibilité est moindre."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Comment automatiser la mise à jour des règles de pare-feu quand Microsoft modifie ses plages d'adresses ?","a":["En supprimant les règles existantes et en laissant le pare-feu apprendre les flux seul","En autorisant tout le trafic sortant vers Internet pour ne plus avoir à les modifier","En interrogeant régulièrement le service web des points de terminaison avec le numéro de version","En remplaçant manuellement toutes les règles chaque année, à la date anniversaire"],"g":2,"e":"Le service web indique si la version a changé et fournit les nouveaux ajouts. Un script ou un connecteur du pare-feu peut ainsi appliquer les modifications."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Pendant les réunions Teams, la synchronisation OneDrive sature la ligne d'un site. Quel réglage est le plus adapté ?","a":["Limiter le débit de synchronisation OneDrive par stratégie, ou le laisser en mode automatique","Désactiver le port UDP 3478 sur le pare-feu du site pendant les réunions","Passer Teams en mode hors connexion pendant toute la durée de la synchronisation","Supprimer le certificat de OneDrive pour interrompre la synchronisation des fichiers"],"g":0,"e":"OneDrive propose de limiter le débit de chargement et de téléchargement. Le mode automatique s'adapte à la bande passante disponible."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Quels enregistrements CNAME permettent l'inscription automatique des appareils Windows dans Intune et Entra ID ?","a":["enterpriseenrollment et enterpriseregistration","autodiscover et lyncdiscover, pour Exchange","_sip._tls et _sipfederationtls._tcp pour Teams","selector1._domainkey et selector2._domainkey"],"g":0,"e":"Ces deux CNAME pointent vers les services d'inscription Microsoft. Ils évitent à l'utilisateur de saisir l'adresse du serveur de gestion."},
  {"theme":"reseau365","level":"legende","format":"single","q":"Comment publie-t-on DKIM pour Exchange Online avec un domaine personnalisé ?","a":["Avec un enregistrement SRV nommé _domainkey._tcp, qui pointe vers Microsoft","Avec deux MX nommés selector1._domainkey et selector2._domainkey, pointant vers Microsoft","Avec deux CNAME, selector1._domainkey et selector2._domainkey, qui pointent vers Microsoft","Avec un seul enregistrement TXT nommé _dkim, qui contient la clé publique du domaine"],"g":2,"e":"Microsoft gère les clés et leur rotation : les deux CNAME renvoient vers les clés hébergées dans le tenant. Il reste à activer la signature dans le portail."},
  {"theme":"reseau365","level":"legende","format":"tf","q":"Il est recommandé de faire passer les médias Teams par un proxy d'inspection pour des raisons de sécurité.","a":["Vrai","Faux"],"g":1,"e":"Faux : Microsoft recommande l'inverse. L'inspection de ce trafic temps réel ajoute de la latence sans bénéfice réel, car il est déjà chiffré."},
  {"theme":"reseau365","level":"legende","format":"multi","q":"Quelles mesures améliorent la qualité de Teams sur un site très chargé ? (plusieurs réponses)","a":["Forcer toutes les réunions à passer en TCP 80","Marquer et prioriser l'audio avec le DSCP","Préférer le câble ou le Wi-Fi 5 GHz","Éviter les détours par un datacenter distant"],"g":[1,2,3],"e":"Priorisation, chemin direct et liaison fiable agissent sur la qualité. Le port TCP 80 n'est pas utilisé pour les médias."},
  {"theme":"reseau365","level":"legende","format":"multi","q":"Quels indicateurs consulte-t-on dans le CQD pour analyser des réunions dégradées ? (plusieurs réponses)","a":["Le type de connexion, câble ou Wi-Fi","La taille de la boîte aux lettres de l'organisateur","La perte de paquets","La gigue"],"g":[0,2,3],"e":"Le CQD croise les mesures réseau avec le bâtiment, le sous-réseau et le type de connexion pour identifier la zone en cause."},
  {"theme":"reseau365","level":"legende","format":"multi","q":"Quelles ouvertures de pare-feu sont nécessaires aux médias Teams ? (plusieurs réponses)","a":["UDP 3478 à 3481 vers les plages des relais Microsoft","TCP 443 vers les points de terminaison Microsoft 365","TCP 3389 vers Internet","UDP 53 vers un DNS public uniquement"],"g":[0,1],"e":"Les médias passent en UDP par les ports 3478 à 3481, avec TCP 443 en repli et pour la signalisation. RDP et un DNS public n'ont rien à voir."},
  {"theme":"reseau365","level":"legende","format":"order","q":"Remets dans l'ordre la mise en place d'une sortie locale pour Microsoft 365 sur un site :","items":["Récupérer la liste des points de terminaison Optimiser et Autoriser","Créer les règles de contournement du proxy et de l'inspection pour ces flux","Faire sortir ces flux directement vers Internet depuis le site (PAC, SD-WAN)","Valider avec le test de connectivité et le CQD"],"e":"On commence par connaître les flux, on adapte les équipements de sécurité, on modifie le routage, puis on mesure le résultat."},
  {"theme":"reseau365","level":"legende","format":"input","q":"Quelle valeur DSCP est recommandée pour le partage d'application de Teams ?","placeholder":"Valeur DSCP","answers":["18","af21","18 (af21)"],"e":"Le partage d'application est marqué AF21 (18), moins prioritaire que l'audio (46) et la vidéo (34)."},
  {"theme":"reseau365","level":"legende","format":"input","q":"Quel est le premier port UDP de la plage 3478 à 3481 utilisée par les médias Teams ?","placeholder":"Numéro de port","answers":["3478","udp 3478","udp/3478"],"e":"Les ports 3478 à 3481 sont utilisés pour les médias. Le port 3478 est aussi celui de STUN/TURN, utilisé pour établir les flux."},
  {"theme":"reseau365","level":"legende","format":"input","q":"Quel sigle désigne le tableau de bord de qualité des appels Teams ? (trois lettres)","placeholder":"Sigle","answers":["CQD"],"e":"Le CQD (Call Quality Dashboard) permet d'analyser par site, sous-réseau ou type de réseau la qualité des appels et des réunions."},
  {"theme":"reseau365","level":"legende","format":"input","q":"Quel est le premier port de la plage source recommandée pour marquer l'audio de Teams avec le QoS ?","placeholder":"Numéro de port","answers":["50000","udp 50000"],"e":"Microsoft recommande, à titre de départ, les ports 50000 à 50019 pour l'audio, 50020 à 50039 pour la vidéo et 50040 à 50059 pour le partage d'application."},
  {"theme":"reseau365","level":"legende","format":"input","q":"Quelle commande Windows affiche la configuration du proxy WinHTTP du poste ?","placeholder":"Commande","answers":["netsh winhttp show proxy"],"e":"netsh winhttp show proxy affiche le proxy utilisé par les services système. Il peut différer de celui du navigateur ou de l'utilisateur."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Que crée un VPN entre un poste en télétravail et le réseau de l'entreprise ?","a":["Un tunnel chiffré à travers Internet","Une copie du serveur de fichiers sur le poste","Un câble dédié entre la maison et le bureau","Un nouveau compte de messagerie"],"g":0,"e":"VPN signifie réseau privé virtuel. Il n'ajoute aucun câble : il protège les échanges qui traversent Internet en les chiffrant dans un tunnel."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Quelle est la différence entre un VPN site à site et un VPN d'accès distant ?","a":["Le site à site ne chiffre pas les données, alors que l'accès distant les chiffre toujours","Le site à site relie deux réseaux entre eux ; l'accès distant relie un utilisateur à un réseau","Le site à site relie les postes d'un même bureau ; l'accès distant relie deux agences entre elles","Le site à site sert uniquement aux mobiles ; l'accès distant sert uniquement aux serveurs"],"g":1,"e":"Un VPN site à site relie par exemple le siège et une agence via leurs pare-feu. L'accès distant relie un poste nomade à l'entreprise grâce à un logiciel client."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Quel protocole de VPN récent, léger et rapide, est intégré au noyau Linux ?","a":["SNMP","Telnet","PPTP","WireGuard"],"g":3,"e":"WireGuard est un protocole moderne, au code très court, intégré au noyau Linux depuis la version 5.6. PPTP est un vieux protocole, Telnet et SNMP ne sont pas des VPN."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Pourquoi le protocole PPTP est-il déconseillé aujourd'hui ?","a":["Il n'existe plus aucun client","Il ne fonctionne qu'en IPv6","Il est considéré comme obsolète et vulnérable","Il impose du matériel spécifique"],"g":2,"e":"PPTP repose sur des mécanismes cryptographiques cassés (MS-CHAPv2, MPPE). On lui préfère IKEv2/IPsec, OpenVPN ou WireGuard.","maj":{"date":"2024-10-01","precision":"mois","texte":"Microsoft déprécie PPTP et L2TP dans Windows Server (RRAS) et recommande IKEv2 ou SSTP.","source":"Microsoft Tech Community","url":"https://techcommunity.microsoft.com/t5/windows-server-news-and-best/pptp-and-l2tp-deprecation-a-new-era-of-secure-connectivity/ba-p/4263956"}},
  {"theme":"vpn","level":"recrue","format":"single","q":"Pourquoi activer l'authentification multifacteur sur un accès VPN ?","a":["Pour compresser les données avant leur envoi afin de réduire la bande passante utilisée","Pour dispenser les utilisateurs de chiffrer les échanges qui traversent le tunnel","Pour accélérer le tunnel en réduisant la charge de chiffrement sur la passerelle","Pour qu'un mot de passe volé ne suffise pas à entrer sur le réseau de l'entreprise"],"g":3,"e":"Le VPN est une porte d'entrée sur le réseau interne. Un second facteur empêche l'utilisation d'un mot de passe dérobé ou deviné."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Que voient les sites Internet quand tout le trafic d'un poste passe par un VPN ?","a":["Aucune adresse IP","L'adresse IP publique de la sortie du VPN","L'adresse MAC du poste","Toujours l'adresse IP du poste à la maison"],"g":1,"e":"Les sites voient l'adresse de la passerelle VPN qui relaie le trafic, pas celle du domicile."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Qu'est-ce que le chiffrement d'un VPN protège ?","a":["Les données qui transitent dans le tunnel","Le disque dur du poste","Les mots de passe enregistrés dans le navigateur","Les fichiers stockés sur le serveur de l'entreprise"],"g":0,"e":"Le VPN protège le transport. Un poste infecté, un disque non chiffré ou un serveur mal protégé restent des problèmes à traiter autrement."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Quel est l'intérêt d'un VPN d'entreprise sur un Wi-Fi public ?","a":["Il empêche tout téléchargement de virus en filtrant les fichiers récupérés sur le Wi-Fi public","Il rend le Wi-Fi public plus rapide en optimisant les échanges avec la passerelle","Il chiffre le trafic entre le poste et l'entreprise, ce qui limite l'écoute sur ce Wi-Fi","Il remplace l'antivirus du poste en bloquant les logiciels malveillants connus"],"g":2,"e":"Sur un Wi-Fi ouvert, un tiers peut observer le trafic. Le tunnel chiffré réduit ce risque, sans dispenser des autres protections du poste."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Que faut-il toujours garder sur un poste en télétravail, en plus du VPN ?","a":["Un pare-feu local désactivé","Un système à jour et un antivirus ou EDR actif","Le même mot de passe sur tous les services","Un mot de passe partagé avec la famille"],"g":1,"e":"Le VPN ne protège pas un poste vulnérable ou infecté : mises à jour, antivirus/EDR et pare-feu local restent indispensables."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Que signifie « tunnel » dans le vocabulaire des VPN ?","a":["Le trafic est copié en parallèle sur deux liaisons pour garantir la disponibilité","Les paquets sont triés par ordre de priorité puis envoyés sur la liaison la plus rapide","Le câble réseau est enterré entre le domicile et les locaux de l'entreprise","Les paquets sont encapsulés dans d'autres paquets pour traverser un réseau intermédiaire"],"g":3,"e":"L'encapsulation place le paquet d'origine, chiffré, dans un nouveau paquet adressé à la passerelle distante."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Après connexion au VPN, un utilisateur n'ouvre plus le serveur de fichiers par son nom, mais l'accès par adresse IP fonctionne. Que vérifier ?","a":["Le serveur DNS fourni par le VPN","La licence Windows","Le thème du bureau","Le câble réseau"],"g":0,"e":"Si l'IP répond et pas le nom, c'est un problème de résolution : le VPN doit pousser les bons serveurs DNS et suffixes."},
  {"theme":"vpn","level":"recrue","format":"single","q":"Quelles informations demande-t-on généralement pour ouvrir une session VPN ?","a":["Le numéro de série de la carte réseau","L'adresse MAC du poste uniquement","Un identifiant, un mot de passe (ou un certificat) et souvent un second facteur","La clé de licence Windows"],"g":2,"e":"Le VPN authentifie l'utilisateur, et parfois l'appareil. Un second facteur (application, clé de sécurité) est fortement recommandé."},
  {"theme":"vpn","level":"recrue","format":"tf","q":"Un VPN rend un poste invulnérable aux attaques.","a":["Vrai","Faux"],"g":1,"e":"Faux : il chiffre le transport mais n'empêche pas l'hameçonnage, les malwares ou l'exploitation d'une faille du poste."},
  {"theme":"vpn","level":"recrue","format":"tf","q":"Un VPN site à site relie deux réseaux, par exemple un siège et une agence.","a":["Vrai","Faux"],"g":0,"e":"Vrai : les deux pare-feu établissent un tunnel permanent, et les agences accèdent aux ressources du siège comme sur un même réseau."},
  {"theme":"vpn","level":"recrue","format":"tf","q":"Un VPN nécessite obligatoirement un câble dédié.","a":["Vrai","Faux"],"g":1,"e":"Faux : un VPN utilise Internet. C'est le chiffrement et l'encapsulation qui créent la liaison privée virtuelle."},
  {"theme":"vpn","level":"recrue","format":"multi","q":"Quels sont des protocoles ou technologies utilisés pour des VPN ? (plusieurs réponses)","a":["WireGuard","IPsec","SMTP","FTP"],"g":[0,1],"e":"IPsec et WireGuard créent des tunnels. SMTP sert aux mails et FTP aux transferts de fichiers."},
  {"theme":"vpn","level":"recrue","format":"multi","q":"Quelles mesures protègent un accès VPN ? (plusieurs réponses)","a":["Un compte unique pour tous les nomades","Un mot de passe partagé par toute l'équipe","Un mot de passe robuste et personnel","Un second facteur d'authentification"],"g":[2,3],"e":"Chaque utilisateur doit avoir son compte, un mot de passe solide et un second facteur. Les comptes partagés empêchent toute traçabilité."},
  {"theme":"vpn","level":"recrue","format":"order","q":"Remets dans l'ordre l'ouverture d'une session VPN depuis un poste en télétravail :","items":["Se connecter à Internet","Lancer le client VPN","S'authentifier (mot de passe et second facteur)","Accéder aux ressources de l'entreprise par le tunnel"],"e":"On a besoin d'Internet pour atteindre la passerelle, puis le client authentifie l'utilisateur et ouvre le tunnel."},
  {"theme":"vpn","level":"recrue","format":"input","q":"Quel sigle désigne l'authentification à plusieurs facteurs ?","placeholder":"Sigle","answers":["MFA","2FA"],"e":"MFA (Multi-Factor Authentication) combine par exemple un mot de passe et un code ou une clé de sécurité."},
  {"theme":"vpn","level":"recrue","format":"input","q":"Que signifie le sigle VPN ? (en anglais)","placeholder":"Les trois mots","answers":["Virtual Private Network"],"e":"VPN : Virtual Private Network, soit réseau privé virtuel."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quels ports faut-il autoriser pour un VPN IPsec avec IKEv2 et traversée de NAT ?","a":["UDP 1194 et TCP 1723","UDP 500 et UDP 4500","TCP 443 uniquement","UDP 51820"],"g":1,"e":"IKE utilise UDP 500 ; en cas de NAT, le trafic ESP est encapsulé dans de l'UDP 4500 (NAT-T). Le 1194 est celui d'OpenVPN, le 1723 celui de PPTP, le 51820 celui de WireGuard."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quel est le rôle d'IKE dans IPsec ?","a":["Router le trafic entre les sites","Attribuer les adresses IP aux clients","Négocier les paramètres de sécurité et échanger les clés","Chiffrer directement les paquets de données"],"g":2,"e":"IKE (Internet Key Exchange) authentifie les extrémités, négocie algorithmes et clés. Le chiffrement des données est ensuite assuré par ESP."},
  {"theme":"vpn","level":"hero","format":"single","q":"Un utilisateur obtient un accès VPN complet au réseau interne. Quel principe réduit le risque ?","a":["Désactiver la journalisation des connexions pour alléger la passerelle","Autoriser tout le trafic entre le VPN et le réseau, sans filtrage par groupe","Donner à tous les utilisateurs le même accès complet, pour simplifier l'administration","Le moindre privilège : n'autoriser que les ressources nécessaires, par groupe"],"g":3,"e":"Un compte compromis ne doit pas ouvrir tout le réseau. On filtre par groupe et par ressource derrière la passerelle VPN."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quel est le principal risque du tunnel partagé (split tunneling) ?","a":["Le trafic hors tunnel échappe aux contrôles de sécurité de l'entreprise (filtrage, proxy)","Le tunnel s'ouvre sans authentification dès que le poste est connecté à Internet","Les mots de passe des utilisateurs transitent en clair entre le poste et la passerelle","Les paquets sont dupliqués sur les deux liaisons, ce qui double la consommation de bande passante"],"g":0,"e":"Avec un tunnel partagé, la navigation Internet sort directement du poste : elle n'est plus filtrée ni journalisée par l'entreprise. On compense par un EDR et un DNS filtrant sur le poste."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quel type de VPN sert de repli quand l'UDP est bloqué, par exemple dans un hôtel ?","a":["Telnet","Un VPN qui passe en TCP 443 (OpenVPN en TCP, SSTP)","PPTP","IKEv1 en mode agressif"],"g":1,"e":"Le port 443 est presque toujours ouvert. Le VPN s'y glisse et ressemble à du trafic HTTPS, au prix de performances un peu moindres."},
  {"theme":"vpn","level":"hero","format":"single","q":"Deux sites utilisent le même plan d'adressage, 192.168.1.0/24, et veulent un VPN site à site. Que se passe-t-il ?","a":["Les deux sites fusionnent en un seul réseau, et tous les postes partagent la même table de routage","Rien de particulier : le VPN modifie automatiquement les adresses de l'un des deux sites","Le tunnel ne chiffre plus les échanges et le trafic circule en clair entre les deux sites","Le routage devient ambigu : il faut changer un plan d'adressage ou utiliser du NAT entre les sites"],"g":3,"e":"Un routeur ne sait pas si une adresse 192.168.1.10 est locale ou distante. Les chevauchements d'adresses sont une cause classique de VPN qui ne fonctionnent pas."},
  {"theme":"vpn","level":"hero","format":"single","q":"À quoi sert la détection de pair mort (DPD) ?","a":["À compresser les paquets","À signer les certificats","À repérer qu'une extrémité du tunnel ne répond plus, pour rétablir le tunnel","À choisir l'algorithme de chiffrement"],"g":2,"e":"La DPD envoie des messages réguliers. Sans réponse, la passerelle supprime la session et peut relancer la négociation."},
  {"theme":"vpn","level":"hero","format":"single","q":"Que garantit le Perfect Forward Secrecy (PFS) ?","a":["La compromission d'une clé ne permet pas de déchiffrer les sessions passées","Le tunnel ne tombe jamais en panne","Les paquets sont plus petits","La clé est identique à chaque session"],"g":0,"e":"Avec le PFS, chaque session dérive de nouveaux secrets Diffie-Hellman. Un attaquant qui obtient une clé plus tard ne peut pas relire le trafic enregistré."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quel est l'avantage d'un certificat plutôt qu'une clé pré-partagée (PSK) pour authentifier un client VPN ?","a":["Chaque client a sa propre identité, révocable individuellement","Le certificat évite d'avoir une passerelle","Le chiffrement est plus rapide","La PSK est interdite par IPsec"],"g":0,"e":"Une PSK commune doit être changée partout si elle fuit. Avec des certificats, on révoque seulement le client concerné (poste perdu, départ d'un salarié)."},
  {"theme":"vpn","level":"hero","format":"single","q":"Comment appelle-t-on l'approche qui donne accès application par application selon l'identité et l'état de l'appareil, sans ouvrir un tunnel réseau complet ?","a":["Un commutateur administrable","Un concentrateur Ethernet","ZTNA (accès réseau Zero Trust)","Un répéteur Wi-Fi"],"g":2,"e":"Le ZTNA ne fait confiance à aucun réseau par défaut : chaque demande est vérifiée. Il remplace progressivement les VPN qui ouvrent l'accès à tout un réseau."},
  {"theme":"vpn","level":"hero","format":"single","q":"Quel mode d'IPsec chiffre le paquet IP d'origine en entier et ajoute un nouvel en-tête IP ?","a":["Le mode promiscuous","Le mode agressif","Le mode transport","Le mode tunnel"],"g":3,"e":"Le mode tunnel protège le paquet complet : c'est celui des VPN entre passerelles. Le mode transport ne protège que les données et sert entre deux hôtes."},
  {"theme":"vpn","level":"hero","format":"tf","q":"Le NAT-T permet à un tunnel IPsec de traverser un NAT en encapsulant ESP dans de l'UDP 4500.","a":["Vrai","Faux"],"g":0,"e":"Vrai : ESP n'ayant pas de ports, un NAT ne sait pas le traduire. L'encapsulation UDP règle le problème."},
  {"theme":"vpn","level":"hero","format":"tf","q":"PPTP est recommandé pour de nouveaux déploiements car il est très rapide.","a":["Vrai","Faux"],"g":1,"e":"Faux : PPTP est obsolète et cassé sur le plan cryptographique. On l'évite, même s'il est rapide."},
  {"theme":"vpn","level":"hero","format":"multi","q":"Quels éléments sont négociés à l'établissement d'un tunnel IPsec ? (plusieurs réponses)","a":["Les clés de session","La langue de l'interface","Le mot de passe du compte Windows","Les algorithmes de chiffrement et d'intégrité"],"g":[0,3],"e":"Les deux extrémités s'accordent sur les algorithmes, les groupes Diffie-Hellman, les durées de vie et les clés de session."},
  {"theme":"vpn","level":"hero","format":"multi","q":"Quels protocoles ou ports interviennent dans un tunnel IPsec ? (plusieurs réponses)","a":["ESP (protocole IP 50)","UDP 500","TCP 22","UDP 123"],"g":[0,1],"e":"UDP 500 pour la négociation IKE et ESP (protocole 50) pour les données. SSH utilise le TCP 22 et NTP l'UDP 123."},
  {"theme":"vpn","level":"hero","format":"order","q":"Remets dans l'ordre l'établissement d'un tunnel IPsec avec IKEv2 :","items":["Les passerelles négocient les algorithmes et font l'échange Diffie-Hellman (IKE_SA_INIT)","Elles s'authentifient mutuellement dans ce canal chiffré (IKE_AUTH)","Elles s'accordent sur les paramètres du tunnel de données (Child SA) et en dérivent les clés","Le trafic des utilisateurs circule chiffré dans le tunnel"],"e":"IKE_SA_INIT établit d'abord un canal chiffré grâce à Diffie-Hellman ; IKE_AUTH authentifie ensuite les extrémités et crée la première Child SA, dont les clés protègent le trafic."},
  {"theme":"vpn","level":"hero","format":"input","q":"Quel est le port UDP par défaut d'OpenVPN ?","placeholder":"Numéro de port","answers":["1194","udp 1194","udp/1194"],"e":"OpenVPN écoute par défaut sur le port 1194, en UDP de préférence. Il peut aussi fonctionner en TCP 443."},
  {"theme":"vpn","level":"hero","format":"input","q":"Quel est le numéro du protocole IP qui transporte les données d'un tunnel IPsec avec ESP ?","placeholder":"Numéro","answers":["50","protocole 50"],"e":"ESP porte le numéro de protocole IP 50 et AH le 51. Ce ne sont ni du TCP ni de l'UDP : un pare-feu doit les autoriser explicitement."},
  {"theme":"vpn","level":"hero","format":"input","q":"Quel protocole VPN de Microsoft passe en TCP 443 ? (quatre lettres)","placeholder":"Sigle","answers":["SSTP"],"e":"SSTP (Secure Socket Tunneling Protocol) encapsule PPP dans une session TLS sur le port 443, ce qui lui permet de traverser presque tous les pare-feu."},
  {"theme":"vpn","level":"hero","format":"input","q":"Quelle commande Windows affiche la table de routage, utile pour voir les routes poussées par le VPN ?","placeholder":"Commande","answers":["route print","netstat -r","netstat -rn","route print -4","Get-NetRoute"],"e":"route print liste les routes du poste, avec leur passerelle et leur métrique. On y voit celles du VPN."},
  {"theme":"vpn","level":"super","format":"single","q":"Quelle différence entre un VPN basé sur les routes et un VPN basé sur les politiques ?","a":["Route-based n'est jamais chiffré","Route-based : un tunnel virtuel vers lequel on route le trafic ; policy-based : le trafic chiffré est désigné par des sélecteurs (réseaux source et destination)","Policy-based n'utilise que de l'UDP","Route-based n'accepte qu'un seul réseau"],"g":1,"e":"Le route-based est plus souple (routage dynamique, plusieurs réseaux). Le policy-based est plus rigide mais courant sur d'anciens équipements."},
  {"theme":"vpn","level":"super","format":"single","q":"Un tunnel IPsec site à site est monté mais le trafic ne passe que dans un sens. Quelle cause est fréquente ?","a":["Des sélecteurs de trafic différents entre les deux extrémités, ou une règle de pare-feu manquante","Le DNS du poste est trop lent","Le tunnel est trop chiffré","L'adresse MAC est dupliquée"],"g":0,"e":"Un tunnel actif prouve que la phase 1 fonctionne. Si le trafic ne passe pas, il faut vérifier les réseaux déclarés, les routes et les règles de filtrage des deux côtés."},
  {"theme":"vpn","level":"super","format":"single","q":"Via le VPN, le ping fonctionne mais des pages web s'ouvrent lentement ou pas du tout. Quelle piste est la plus probable ?","a":["Le ping passe par un autre tunnel chiffré que celui utilisé par les navigateurs web","Le certificat de la passerelle est expiré depuis plusieurs jours","Un problème de MTU ou de MSS : les gros paquets sont fragmentés ou perdus","Le DNS du poste n'est pas chiffré par le tunnel VPN"],"g":2,"e":"L'encapsulation ajoute des en-têtes : la MTU utile du tunnel est plus petite. Les petits paquets passent, pas les gros, si la fragmentation est bloquée."},
  {"theme":"vpn","level":"super","format":"single","q":"Quel réglage corrige souvent ce problème de MTU dans un VPN ?","a":["Désactiver complètement la résolution de noms sur l'interface du tunnel VPN","Augmenter la valeur du TTL des paquets émis par le client VPN","Activer IPv6 sur toutes les interfaces du poste","Abaisser la MTU de l'interface du tunnel ou régler le MSS (clamping)"],"g":3,"e":"Le MSS clamping réduit la taille des segments TCP pour qu'ils tiennent dans le tunnel. Valeur courante : MTU 1400 ou MSS autour de 1360."},
  {"theme":"vpn","level":"super","format":"single","q":"Qu'appelle-t-on une fuite DNS avec un VPN ?","a":["Des requêtes DNS qui sortent par le réseau local au lieu du tunnel, révélant les sites visités","Un cache DNS trop long sur le poste, qui conserve d'anciennes adresses après la déconnexion du VPN","Un serveur DNS qui chiffre trop de requêtes et ralentit la connexion du tunnel","Une panne du serveur DNS interne qui empêche la résolution des noms de l'entreprise"],"g":0,"e":"Si le client interroge le DNS du Wi-Fi ou du fournisseur au lieu de celui du VPN, les noms demandés sont visibles, voire détournés."},
  {"theme":"vpn","level":"super","format":"single","q":"À quoi sert un kill switch dans un client VPN ?","a":["À désactiver définitivement la carte Wi-Fi du poste dès que l'utilisateur quitte le bureau","À éteindre le poste dès que la connexion au VPN est perdue pendant la nuit","À supprimer les journaux de connexion pour protéger la vie privée de l'utilisateur","À couper le trafic quand le tunnel tombe, pour éviter que les données sortent hors tunnel"],"g":3,"e":"Sans kill switch, une coupure du tunnel replace le poste sur son réseau local, et le trafic non protégé part en clair."},
  {"theme":"vpn","level":"super","format":"single","q":"Quelle fonction de Windows connecte automatiquement l'appareil à l'entreprise avant l'ouverture de session, avec un tunnel appareil ?","a":["Windows Hello","Un réseau virtuel Hyper-V","Always On VPN","Le Bureau à distance"],"g":2,"e":"Always On VPN permet un tunnel appareil (gestion, mises à jour, ouverture de session de domaine) et un tunnel utilisateur (accès aux ressources)."},
  {"theme":"vpn","level":"super","format":"single","q":"Quel risque spécifique présente le mode agressif d'IKEv1 avec une clé pré-partagée ?","a":["Les paquets sont dupliqués","Le hash de la PSK peut être capturé et cassé hors ligne","Le tunnel utilise DES","Les certificats expirent immédiatement"],"g":1,"e":"Le mode agressif envoie l'identité et un hash dérivé de la PSK en clair. Un attaquant peut tenter de le casser par force brute. IKEv2 et les certificats règlent ce point."},
  {"theme":"vpn","level":"super","format":"single","q":"Pourquoi des entreprises passent-elles du VPN classique au ZTNA ?","a":["Pour réduire le coût des licences Windows et des postes fournis aux collaborateurs","Pour supprimer l'authentification des utilisateurs et simplifier l'accès aux applications","Pour donner accès application par application selon l'identité et l'état de l'appareil, plutôt qu'au réseau entier","Pour donner accès à tout le réseau interne dès l'authentification, sans vérifier l'état de l'appareil du collaborateur"],"g":2,"e":"Un VPN classique place l'utilisateur sur le réseau interne : un compte compromis peut s'y déplacer. Le ZTNA limite l'accès à ce qui est nécessaire et vérifie le contexte en continu."},
  {"theme":"vpn","level":"super","format":"single","q":"Quel protocole VPN est géré nativement par le client VPN intégré de Windows ?","a":["OpenVPN","IKEv2","GRE seul","WireGuard"],"g":1,"e":"Windows gère nativement IKEv2, SSTP, L2TP/IPsec et PPTP. WireGuard et OpenVPN demandent un logiciel client supplémentaire."},
  {"theme":"vpn","level":"super","format":"single","q":"Quelle option d'Azure VPN Gateway relie un poste isolé à un réseau virtuel Azure ?","a":["Le peering de réseaux virtuels","Site à site (S2S) uniquement","ExpressRoute uniquement","Point à site (P2S)"],"g":3,"e":"Le point à site connecte un poste individuel avec OpenVPN ou IKEv2. SSTP est en cours de retrait : on ne peut plus l'activer depuis le 31 août 2026 et les connexions SSTP s'arrêteront le 31 mars 2027. Le site à site relie un réseau local entier à Azure.","maj":{"date":"2026-08-31","texte":"Microsoft ne permet plus d'activer SSTP sur Azure VPN Gateway ; les connexions SSTP existantes s'arrêteront le 31 mars 2027.","source":"Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/vpn-gateway/ikev2-openvpn-from-sstp"}},
  {"theme":"vpn","level":"super","format":"single","q":"Quel est l'intérêt d'un bastion pour administrer des serveurs ?","a":["Un point d'entrée unique, durci et journalisé, vers les serveurs d'administration","Il accélère le VPN en regroupant les tunnels de tous les administrateurs sur un seul lien","Il stocke les sauvegardes des serveurs dans une zone chiffrée et isolée du réseau","Il remplace le pare-feu en filtrant tout le trafic entrant vers le réseau interne"],"g":0,"e":"Un bastion concentre les accès d'administration : on peut y imposer le MFA, enregistrer les sessions et limiter l'exposition des serveurs."},
  {"theme":"vpn","level":"super","format":"tf","q":"Un client VPN configuré en tunnel complet envoie tout son trafic Internet par la passerelle de l'entreprise.","a":["Vrai","Faux"],"g":0,"e":"Vrai : en tunnel complet, la route par défaut passe par le VPN. L'entreprise peut filtrer le trafic, mais la passerelle doit absorber la charge."},
  {"theme":"vpn","level":"super","format":"tf","q":"Un VPN chiffre aussi les données stockées sur le disque du poste.","a":["Vrai","Faux"],"g":1,"e":"Faux : le VPN protège les données en transit. Le chiffrement du disque (BitLocker) est une mesure distincte."},
  {"theme":"vpn","level":"super","format":"multi","q":"Quelles causes fréquentes expliquent un tunnel IPsec qui ne monte pas ? (plusieurs réponses)","a":["Une clé pré-partagée différente d'un côté à l'autre","Un mot de passe d'imprimante expiré","Des propositions de chiffrement ou de groupe Diffie-Hellman incompatibles","Un serveur de fichiers éteint"],"g":[0,2],"e":"La phase 1 échoue quand les deux extrémités ne s'accordent pas sur les paramètres ou sur le secret. Les serveurs de fichiers n'y sont pour rien."},
  {"theme":"vpn","level":"super","format":"multi","q":"Quelles mesures renforcent un accès VPN d'entreprise ? (plusieurs réponses)","a":["Une authentification multifacteur","Des alertes sur les connexions inhabituelles","Un mot de passe partagé par service","Une limitation des ressources accessibles par groupe"],"g":[0,1,3],"e":"Authentification forte, supervision et moindre privilège réduisent le risque. Un mot de passe partagé détruit toute traçabilité."},
  {"theme":"vpn","level":"super","format":"order","q":"Remets dans l'ordre le dépannage d'un VPN site à site qui ne passe plus :","items":["Vérifier l'état du tunnel (phases 1 et 2) sur chaque passerelle","Contrôler les sélecteurs de trafic et les routes","Examiner les règles de pare-feu des deux côtés","Tester avec un ping, puis avec une application réelle en surveillant la MTU"],"e":"On part de l'état du tunnel, puis des routes et des filtres, avant d'affiner avec des tests réels qui révèlent les problèmes de taille de paquet."},
  {"theme":"vpn","level":"super","format":"input","q":"Quel est le port UDP par défaut de WireGuard ?","placeholder":"Numéro de port","answers":["51820","udp 51820","udp/51820"],"e":"WireGuard utilise par défaut le port UDP 51820, modifiable dans la configuration."},
  {"theme":"vpn","level":"super","format":"input","q":"Quel sigle de quatre lettres désigne l'accès réseau « zéro confiance » par application ?","placeholder":"Sigle","answers":["ZTNA"],"e":"ZTNA (Zero Trust Network Access) remplace ou complète le VPN : l'accès est accordé application par application après vérification."},
  {"theme":"vpn","level":"super","format":"input","q":"Quelle est la MTU standard (en octets) d'un lien Ethernet, que l'encapsulation d'un VPN vient réduire ?","placeholder":"Nom de la technique","answers":["1500","1500 octets"],"e":"Ethernet transporte des paquets IP de 1500 octets au plus. Le tunnel ajoute ses en-têtes : wg-quick règle par exemple WireGuard sur 1420 par défaut, et on réduit le MSS TCP en conséquence (MSS clamping)."},
  {"theme":"vpn","level":"legende","format":"single","q":"Dans WireGuard, comment un pair est-il identifié et autorisé ?","a":["Par sa clé publique, associée à la liste d'adresses IP autorisées (AllowedIPs)","Par un mot de passe partagé, associé à un identifiant d'utilisateur côté serveur","Par son adresse MAC, associée à une liste de ports autorisés sur le pare-feu","Par un certificat X.509 émis par l'autorité de certification de l'entreprise"],"g":0,"e":"WireGuard fonctionne par « cryptokey routing » : chaque pair déclare sa clé publique et les adresses qui peuvent passer par lui. Pas d'autorité de certification ni de négociation."},
  {"theme":"vpn","level":"legende","format":"single","q":"Que fait AllowedIPs = 0.0.0.0/0 dans la configuration d'un client WireGuard ?","a":["Il limite le débit à zéro","Il désactive le chiffrement","Il autorise tous les pairs à se connecter","Il envoie tout le trafic IPv4 dans le tunnel (tunnel complet)"],"g":3,"e":"AllowedIPs sert à la fois de filtre et de table de routage. 0.0.0.0/0 fait passer toutes les destinations IPv4 par le tunnel."},
  {"theme":"vpn","level":"legende","format":"single","q":"Quelle attaque exploite des identifiants volés ailleurs pour se connecter à un VPN protégé uniquement par mot de passe ?","a":["L'usurpation ARP","Le DNS rebinding","Le bourrage d'identifiants (credential stuffing)","Une attaque smurf"],"g":2,"e":"L'attaquant teste des couples identifiant/mot de passe issus d'autres fuites. L'authentification multifacteur et le blocage après échecs répétés limitent l'attaque."},
  {"theme":"vpn","level":"legende","format":"single","q":"Dans un déploiement Always On VPN avec tunnel appareil et tunnel utilisateur, à quoi sert le tunnel appareil ?","a":["À chiffrer uniquement les échanges de messagerie, une fois l'utilisateur authentifié et sa session ouverte sur le poste","À joindre l'entreprise avant l'ouverture de session (domaine, mises à jour, gestion), sans action de l'utilisateur","À gérer l'impression et le partage de fichiers entre les postes connectés au domicile","À remplacer le tunnel utilisateur lorsque celui-ci est coupé par le pare-feu local"],"g":1,"e":"Le tunnel appareil se monte au démarrage et permet l'ouverture de session de domaine et la gestion à distance. Le tunnel utilisateur donne ensuite accès aux ressources."},
  {"theme":"vpn","level":"legende","format":"single","q":"Pourquoi AES-GCM est-il préféré à AES-CBC avec HMAC dans un IPsec moderne ?","a":["Il utilise des clés plus courtes, ce qui réduit le temps de calcul sur la passerelle","Il chiffre et authentifie en une seule opération (AEAD), avec de bonnes performances","Il n'a pas besoin d'échange de clés car la clé est fixée à l'avance sur les deux pairs","Il reste compatible avec PPTP, ce qui simplifie la migration des anciens clients"],"g":1,"e":"Un mode AEAD fournit confidentialité et intégrité ensemble, ce qui limite les erreurs de conception et profite de l'accélération matérielle."},
  {"theme":"vpn","level":"legende","format":"single","q":"Quel est le rôle de l'algorithme Diffie-Hellman dans IKE ?","a":["Compresser les données","Signer les certificats","Établir un secret partagé sans le faire transiter sur le réseau","Authentifier le mot de passe de l'utilisateur"],"g":2,"e":"Les deux extrémités calculent le même secret à partir d'échanges publics. Un observateur ne peut pas le reconstituer."},
  {"theme":"vpn","level":"legende","format":"single","q":"En tunnel complet, un utilisateur n'accède plus à l'imprimante de son domicile. Quelle option y répond ?","a":["Autoriser l'accès au réseau local ou passer en tunnel partagé","Utiliser un autre serveur DNS","Désactiver le chiffrement","Changer le port du VPN"],"g":0,"e":"La route par défaut passe dans le tunnel, y compris pour le réseau local. Certains clients proposent d'exclure le réseau local, au prix d'un contrôle moindre."},
  {"theme":"vpn","level":"legende","format":"single","q":"Quelle est la différence entre OpenVPN en mode tun et en mode tap ?","a":["tun est utilisé côté serveur uniquement, alors que tap est réservé aux clients","tun est chiffré par défaut alors que tap transporte les données en clair","tun fonctionne en UDP uniquement, alors que tap fonctionne en TCP uniquement","tun transporte des paquets IP (couche 3), tap des trames Ethernet (couche 2)"],"g":3,"e":"tun suffit pour un accès distant routé. tap permet de relier des réseaux comme un pont, par exemple pour du broadcast, mais avec plus de trafic."},
  {"theme":"vpn","level":"legende","format":"single","q":"Que signifie l'expiration de la durée de vie d'une SA IPsec ?","a":["Le tunnel est supprimé définitivement et l'administrateur doit le recréer à la main","Le mot de passe de l'utilisateur expire et il doit en choisir un nouveau pour pouvoir se reconnecter au tunnel","Le certificat de la passerelle est révoqué et tous les clients sont déconnectés","Les clés sont renégociées (rekey) pour limiter la quantité de trafic protégé par une même clé"],"g":3,"e":"La durée de vie, en temps ou en volume, force un renouvellement. Une clé compromise ne donne accès qu'à une fenêtre limitée."},
  {"theme":"vpn","level":"legende","format":"single","q":"Pourquoi centraliser les journaux de connexion VPN dans un SIEM ?","a":["Pour accélérer le tunnel en répartissant la charge entre plusieurs passerelles VPN","Pour supprimer la nécessité de limiter les accès par groupe, en détectant toutes les intrusions à leur place","Pour détecter des accès anormaux (pays inhabituel, horaires, échecs répétés) en les corrélant avec d'autres événements","Pour compresser les paquets afin de réduire l'espace de stockage utilisé par les journaux"],"g":2,"e":"Un compte compromis se repère par son comportement : connexion depuis un pays inattendu, impossible voyage, rafales d'échecs. Le SIEM permet de les croiser avec le reste."},
  {"theme":"vpn","level":"legende","format":"tf","q":"Le protocole PPTP utilise le port TCP 1723 et le protocole GRE.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le contrôle passe par TCP 1723 et les données par GRE (protocole IP 47). Ce besoin de GRE complique son passage dans un NAT."},
  {"theme":"vpn","level":"legende","format":"multi","q":"Quels contrôles réduisent le risque lié à un compte VPN volé ? (plusieurs réponses)","a":["Un MFA résistant au hameçonnage (FIDO2)","Des alertes sur les connexions depuis un pays inhabituel","Un accès conditionnel selon l'appareil et la localisation","Un mot de passe sans expiration, sans autre contrôle"],"g":[0,1,2],"e":"On combine authentification forte, conditions d'accès et supervision. Un simple mot de passe sans autre protection ne suffit pas."},
  {"theme":"vpn","level":"legende","format":"multi","q":"Que négocie-t-on lors de la création d'un tunnel de données IPsec (Child SA) ? (plusieurs réponses)","a":["La langue de l'interface du client","Les algorithmes de chiffrement et d'intégrité des données","Les réseaux protégés (sélecteurs de trafic)","Le mot de passe du compte utilisateur"],"g":[1,2],"e":"Le Child SA décrit les données protégées : algorithmes, clés, sélecteurs de trafic. L'authentification de l'utilisateur est un autre sujet."},
  {"theme":"vpn","level":"legende","format":"multi","q":"Quels symptômes évoquent un problème de MTU dans un VPN ? (plusieurs réponses)","a":["Le ping de petits paquets passe mais certains transferts bloquent","Un message « mot de passe invalide »","Une connexion TLS qui se fige après le début de la négociation","Le tunnel ne monte jamais (phase 1)"],"g":[0,2],"e":"Les petits paquets passent, les gros sont perdus : le symptôme typique de la MTU. Une phase 1 qui échoue ou un refus d'authentification relèvent d'autres causes."},
  {"theme":"vpn","level":"legende","format":"order","q":"Remets dans l'ordre le déploiement d'un accès distant sécurisé pour des télétravailleurs :","items":["Définir les ressources à exposer et les groupes autorisés","Mettre en place l'authentification forte et l'accès conditionnel","Configurer la passerelle et les règles de filtrage par groupe","Déployer le client et superviser les connexions (journaux, alertes)"],"e":"On part du besoin et du moindre privilège, puis on sécurise l'identité, on configure l'accès, et on supervise."},
  {"theme":"vpn","level":"legende","format":"input","q":"Quel port UDP utilise L2TP (encapsulé dans IPsec dans L2TP/IPsec) ?","placeholder":"Numéro de port","answers":["1701","udp 1701","udp/1701"],"e":"L2TP utilise UDP 1701 et ne chiffre rien seul : on le protège avec IPsec (UDP 500, 4500 et ESP). Microsoft a déprécié PPTP et L2TP dans le serveur RRAS de Windows Server (octobre 2024) au profit d'IKEv2 et SSTP.","maj":{"date":"2024-10-01","precision":"mois","texte":"Microsoft déprécie PPTP et L2TP dans Windows Server (RRAS) et recommande IKEv2 ou SSTP.","source":"Microsoft Tech Community","url":"https://techcommunity.microsoft.com/t5/windows-server-news-and-best/pptp-and-l2tp-deprecation-a-new-era-of-secure-connectivity/ba-p/4263956"}},
  {"theme":"vpn","level":"legende","format":"input","q":"Quel est le numéro de protocole IP utilisé par GRE ?","placeholder":"Numéro","answers":["47","protocole 47"],"e":"GRE porte le numéro de protocole 47. Il faut l'autoriser sur un pare-feu pour qu'un tunnel GRE (ou PPTP) fonctionne."},
  {"theme":"vpn","level":"legende","format":"input","q":"Quelle option de la commande ping sous Windows interdit la fragmentation, pour tester la MTU d'un chemin ?","placeholder":"Option","answers":["-f","ping -f","/f"],"e":"ping -f -l 1472 destination envoie un paquet qui ne doit pas être fragmenté. On augmente ou diminue la taille jusqu'à trouver la limite."},
  {"theme":"vpn","level":"legende","format":"input","q":"Quelle cmdlet PowerShell crée une connexion VPN dans Windows ?","placeholder":"Cmdlet","answers":["Add-VpnConnection"],"e":"Add-VpnConnection crée un profil VPN avec son protocole, sa passerelle et ses méthodes d'authentification. Set-VpnConnection le modifie."},
  {"theme":"vpn","level":"legende","format":"input","q":"Quelle commande Linux (strongSwan) affiche l'état détaillé des tunnels IPsec ?","placeholder":"Commande","answers":["ipsec statusall","swanctl --list-sas","swanctl -l","ipsec status"],"e":"ipsec statusall (ancienne syntaxe) ou swanctl --list-sas (syntaxe moderne) montrent les associations de sécurité établies, leurs algorithmes et leurs compteurs de trafic."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Pourquoi séparer les postes de la comptabilité et ceux des visiteurs dans deux VLAN ?","a":["Pour supprimer le besoin de mots de passe sur les postes de chaque groupe","Pour isoler leurs échanges et limiter la diffusion du trafic entre les deux groupes","Pour doubler le débit disponible de chaque groupe en séparant leur trafic","Pour que les deux groupes partagent la même adresse IP et la même passerelle"],"g":1,"e":"Un VLAN regroupe des ports de commutateur en un réseau logique. On sépare ainsi les populations, sans acheter de commutateurs supplémentaires."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Que faut-il pour que deux postes de VLAN différents communiquent ?","a":["Un routeur ou un commutateur de niveau 3 qui route entre les VLAN","Un second serveur DNS déclaré dans chacun des deux VLAN","Un serveur DHCP unique qui distribue des adresses aux deux VLAN","Un répéteur Ethernet placé entre les deux commutateurs"],"g":0,"e":"Chaque VLAN est un réseau à part. Pour passer de l'un à l'autre, il faut un équipement qui route, et c'est là qu'on applique les règles de filtrage."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Quel type de port d'un commutateur est relié à un poste de travail et appartient à un seul VLAN ?","a":["Un port trunk","Un port d'empilage","Un port d'accès (access)","Un port miroir"],"g":2,"e":"Un port d'accès appartient à un seul VLAN et ne porte pas d'étiquette. Le poste n'a pas conscience du VLAN."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Quel type de lien transporte plusieurs VLAN entre deux commutateurs ?","a":["Un lien d'accès","Un lien console","Un lien d'alimentation PoE","Un lien trunk (802.1Q)"],"g":3,"e":"Un trunk porte plusieurs VLAN sur le même lien, chaque trame étant étiquetée avec l'identifiant de son VLAN (norme IEEE 802.1Q)."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Que désigne la passerelle par défaut d'un poste ?","a":["L'adresse de l'imprimante réseau utilisée par défaut sur le poste","L'adresse du serveur DHCP qui distribue la configuration IP du réseau","L'adresse du routeur qui permet de sortir de son réseau local","L'adresse du serveur DNS qui traduit les noms en adresses"],"g":2,"e":"Pour toute destination hors de son réseau, le poste envoie ses paquets à sa passerelle. Sans elle, il ne joint que son propre réseau."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Que contient une table de routage ?","a":["Les mots de passe des équipements voisins et leurs clés d'authentification","La liste des VLAN configurés et des ports qui leur sont affectés","La liste des adresses MAC des postes et des ports sur lesquels ils sont connectés","Les réseaux connus et le chemin pour les atteindre (prochain saut ou interface)"],"g":3,"e":"Pour chaque destination, la table indique par où passer. Le routeur compare l'adresse du paquet à ces entrées."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Que signifie la route par défaut 0.0.0.0/0 ?","a":["Seul le réseau local directement connecté est autorisé à communiquer","Tout ce qui n'est pas couvert par une route plus précise passe par là","Le réseau est désactivé et aucune route ne peut plus être utilisée","Toutes les adresses sont bloquées tant qu'une route précise n'existe pas"],"g":1,"e":"0.0.0.0/0 correspond à toute adresse. C'est le chemin de dernier recours, en général vers Internet."},
  {"theme":"vlan","level":"recrue","format":"single","q":"À quoi correspond en général un VLAN sur le plan IP ?","a":["À un sous-réseau IP distinct","À un serveur DHCP unique pour toute l'entreprise","À un câble réseau physique distinct","À un nom de domaine"],"g":0,"e":"Par convention, un VLAN = un sous-réseau : par exemple VLAN 10 en 192.168.10.0/24 et VLAN 20 en 192.168.20.0/24."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Quel est l'effet d'un VLAN sur le trafic de diffusion (broadcast) ?","a":["Il l'étend à tous les VLAN, qui forment alors un seul domaine de diffusion","Il le limite au VLAN : chaque VLAN est un domaine de diffusion distinct","Il le chiffre pour empêcher l'écoute par les postes des autres VLAN","Il le supprime complètement, car chaque poste est isolé des autres"],"g":1,"e":"Une diffusion ne traverse pas les VLAN. Réduire la taille des domaines de diffusion améliore les performances et la sécurité."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Quelle est la différence entre un commutateur de niveau 2 et un commutateur de niveau 3 ?","a":["Le niveau 3 sait aussi router entre réseaux IP","Le niveau 3 fonctionne sans câble","Le niveau 2 ne gère pas les VLAN","Le niveau 3 a plus de ports"],"g":0,"e":"Un commutateur de niveau 2 transmet selon les adresses MAC. Celui de niveau 3 ajoute le routage IP, et peut porter les passerelles des VLAN."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Dans quel cas le routage statique convient-il ?","a":["Un grand réseau qui change tout le temps","Un réseau sans routeur","Uniquement un Wi-Fi invité","Un petit réseau stable, avec peu de routes à saisir à la main"],"g":3,"e":"Les routes statiques sont simples et prévisibles, mais elles ne s'adaptent pas seules aux pannes. On les réserve aux petits réseaux ou à des cas précis."},
  {"theme":"vlan","level":"recrue","format":"single","q":"Pourquoi isoler la téléphonie IP dans un VLAN voix ?","a":["Pour éviter d'avoir à utiliser un commutateur dans la salle","Pour lui attribuer une adresse MAC dédiée, distincte de celle des postes","Pour la prioriser et la séparer du trafic des postes de travail","Parce que la téléphonie IP ne fonctionne qu'avec le VLAN 1"],"g":2,"e":"Le VLAN voix permet d'appliquer des règles de priorité (QoS) et de limiter l'écoute du trafic téléphonique."},
  {"theme":"vlan","level":"recrue","format":"tf","q":"Sans routage, deux postes situés dans des VLAN différents ne peuvent pas communiquer.","a":["Vrai","Faux"],"g":0,"e":"Vrai : chaque VLAN est un réseau séparé. Il faut un routeur ou un commutateur de niveau 3 pour passer de l'un à l'autre."},
  {"theme":"vlan","level":"recrue","format":"tf","q":"Un VLAN nécessite autant de commutateurs que de réseaux distincts.","a":["Vrai","Faux"],"g":1,"e":"Faux : c'est justement l'intérêt des VLAN. Plusieurs réseaux logiques coexistent sur les mêmes commutateurs."},
  {"theme":"vlan","level":"recrue","format":"tf","q":"Un port trunk ne transporte jamais que le trafic d'un seul VLAN.","a":["Vrai","Faux"],"g":1,"e":"Faux : un trunk transporte plusieurs VLAN, chaque trame portant l'étiquette de son VLAN."},
  {"theme":"vlan","level":"recrue","format":"multi","q":"Quels équipements peuvent router entre des VLAN ? (plusieurs réponses)","a":["Un répéteur Wi-Fi","Un commutateur de niveau 3","Un concentrateur (hub)","Un routeur"],"g":[1,3],"e":"Seuls les équipements de niveau 3 routent entre réseaux IP. Un hub ou un répéteur ne font que relayer les signaux."},
  {"theme":"vlan","level":"recrue","format":"multi","q":"Quels avantages apportent les VLAN ? (plusieurs réponses)","a":["Des domaines de diffusion plus petits","Une segmentation logique des postes","Un chiffrement automatique du trafic","Plus de bande passante sur chaque lien"],"g":[0,1],"e":"Les VLAN séparent et organisent le réseau, mais ne chiffrent rien ni n'augmentent le débit des liens."},
  {"theme":"vlan","level":"recrue","format":"order","q":"Remets dans l'ordre le trajet d'un paquet d'un poste du VLAN 10 vers un poste du VLAN 20 :","items":["Le poste A envoie le paquet à sa passerelle (routeur)","Le routeur consulte sa table de routage","Le routeur transmet le paquet dans le VLAN 20","Le poste B reçoit le paquet"],"e":"Le poste ne peut pas joindre directement un autre réseau : il passe par sa passerelle, qui route puis réexpédie dans le VLAN de destination."},
  {"theme":"vlan","level":"recrue","format":"input","q":"Quelle est la route par défaut en IPv4, écrite avec la notation CIDR ?","placeholder":"Route","answers":["0.0.0.0/0"],"e":"0.0.0.0/0 désigne toutes les adresses IPv4. Elle sert quand aucune route plus précise ne correspond."},
  {"theme":"vlan","level":"recrue","format":"input","q":"Quelle norme IEEE définit l'étiquetage des VLAN sur un trunk ? (802.1…)","placeholder":"Norme","answers":["802.1Q","802.1q","ieee 802.1q"],"e":"IEEE 802.1Q ajoute à la trame Ethernet une étiquette de 4 octets qui contient l'identifiant du VLAN."},
  {"theme":"vlan","level":"hero","format":"single","q":"Qu'est-ce que le VLAN natif d'un trunk 802.1Q ?","a":["Le VLAN de secours en cas de panne","Le VLAN qui reçoit tout le trafic inconnu","Le VLAN d'administration réservé","Le VLAN dont les trames circulent sans étiquette sur le trunk"],"g":3,"e":"Les trames du VLAN natif ne sont pas étiquetées. Les deux extrémités doivent s'accorder sur lui, sinon les trames atterrissent dans un mauvais VLAN."},
  {"theme":"vlan","level":"hero","format":"single","q":"Quelle technique relie plusieurs VLAN à un seul routeur par un seul lien physique, grâce à des sous-interfaces ?","a":["Le Spanning Tree","Router on a stick","La recopie de port (port mirroring)","L'EtherChannel"],"g":1,"e":"Le routeur reçoit un trunk et dispose d'une sous-interface par VLAN (par exemple g0/0.10), chacune avec son adresse de passerelle."},
  {"theme":"vlan","level":"hero","format":"single","q":"Qu'est-ce qu'une interface SVI sur un commutateur de niveau 3 ?","a":["Une interface de console utilisée pour administrer le commutateur depuis un poste du VLAN","Une copie de sauvegarde de la configuration du VLAN sur le commutateur","Une interface virtuelle associée à un VLAN, qui sert de passerelle à ses postes","Un port physique de sortie, relié directement au routeur voisin"],"g":2,"e":"La SVI (Switch Virtual Interface) porte l'adresse IP du VLAN sur le commutateur. Avec ip routing, il route entre toutes ses SVI."},
  {"theme":"vlan","level":"hero","format":"single","q":"Un poste d'un VLAN ne reçoit pas d'adresse IP car le serveur DHCP est dans un autre VLAN. Quelle configuration résout le problème ?","a":["Un relais DHCP (ip helper-address) sur la passerelle du VLAN","Le VLAN 1 activé sur toutes les interfaces du commutateur","Un second serveur DNS déclaré dans la configuration du VLAN","Un trunk natif configuré sur la carte réseau du poste"],"g":0,"e":"Le DHCPDISCOVER est une diffusion : elle ne traverse pas les VLAN. Le relais la transforme en requête unicast vers le serveur."},
  {"theme":"vlan","level":"hero","format":"single","q":"Quelle commande Cisco affiche la liste des VLAN et leurs ports ?","a":["show ip route","display vlans","show vlan brief","show running-vlan"],"g":2,"e":"show vlan brief liste les VLAN actifs avec leur nom et les ports d'accès qui leur sont affectés. Les ports trunk n'y apparaissent pas."},
  {"theme":"vlan","level":"hero","format":"single","q":"Deux routes couvrent la destination : 10.1.0.0/16 et 10.1.2.0/24. Laquelle est utilisée ?","a":["Aucune des deux : le routeur signale un conflit de routes","10.1.2.0/24, car c'est la plus précise (plus long préfixe)","10.1.0.0/16, car elle couvre un plus grand nombre d'adresses","Les deux en alternance, pour répartir le trafic équitablement"],"g":1,"e":"Le routeur choisit toujours le plus long préfixe correspondant, avant de comparer distances et métriques."},
  {"theme":"vlan","level":"hero","format":"single","q":"Qu'est-ce que la distance administrative d'une route ?","a":["Un indice de confiance dans la source de la route : plus il est bas, plus la route est préférée","La distance physique en mètres entre les routeurs : plus elle est courte, plus la route est préférée","Le débit du lien : plus il est élevé, plus la route est préférée","Le nombre de sauts nécessaires pour atteindre le réseau de destination"],"g":0,"e":"Si une même destination est connue par OSPF et par une route statique, la source la plus fiable (distance la plus basse) l'emporte."},
  {"theme":"vlan","level":"hero","format":"single","q":"Parmi ces sources de routes, laquelle a la distance administrative la plus basse ?","a":["OSPF","Une route statique","RIP","Un réseau directement connecté"],"g":3,"e":"Réseau connecté : 0 ; route statique : 1 ; OSPF : 110 ; RIP : 120."},
  {"theme":"vlan","level":"hero","format":"single","q":"Pourquoi limiter les VLAN autorisés sur un trunk (allowed vlan) ?","a":["Pour activer le routage","Pour réduire la diffusion inutile et la surface d'attaque","Pour augmenter le nombre de VLAN utilisables","Pour changer le VLAN natif"],"g":1,"e":"Par défaut, un trunk transporte tous les VLAN. N'autoriser que ceux qui sont nécessaires limite le trafic et les possibilités d'accès."},
  {"theme":"vlan","level":"hero","format":"single","q":"Quel protocole de routage dynamique est un protocole interne à état de liens, très courant en entreprise ?","a":["BGP","RIP version 1","OSPF","STP"],"g":2,"e":"OSPF (Open Shortest Path First) calcule les meilleurs chemins avec l'algorithme de Dijkstra. BGP sert entre opérateurs, RIP est ancien et STP gère les boucles de niveau 2."},
  {"theme":"vlan","level":"hero","format":"single","q":"Quel est l'intérêt du routage dynamique par rapport au routage statique ?","a":["Il chiffre le trafic de routage et les données des utilisateurs","Il n'a besoin d'aucune configuration, car les routeurs se découvrent entre eux seuls","Il consomme moins de bande passante, car il n'échange aucune annonce","Les routes s'adaptent automatiquement aux pannes et aux changements du réseau"],"g":3,"e":"Les routeurs échangent leurs informations et recalculent les chemins. C'est indispensable dans un réseau à plusieurs liens."},
  {"theme":"vlan","level":"hero","format":"tf","q":"Sur un port d'accès, les trames portent une étiquette 802.1Q.","a":["Vrai","Faux"],"g":1,"e":"Faux : sur un port d'accès, les trames circulent sans étiquette. C'est le commutateur qui leur associe le VLAN du port."},
  {"theme":"vlan","level":"hero","format":"tf","q":"Le VLAN 1 est le VLAN par défaut de la plupart des commutateurs.","a":["Vrai","Faux"],"g":0,"e":"Vrai : tous les ports y sont affectés à la sortie d'usine. On conseille de ne pas s'en servir pour les postes ni pour l'administration."},
  {"theme":"vlan","level":"hero","format":"multi","q":"Quelles commandes Cisco font partie de la configuration d'un port d'accès dans le VLAN 10 ? (plusieurs réponses)","a":["switchport mode access","ip routing","switchport trunk allowed vlan 10","switchport access vlan 10"],"g":[0,3],"e":"Un port d'accès se configure en mode access puis rattaché à son VLAN. Les commandes trunk concernent les liens entre commutateurs."},
  {"theme":"vlan","level":"hero","format":"multi","q":"Quelles informations contient une route statique ? (plusieurs réponses)","a":["L'adresse MAC de la destination finale","Le prochain saut ou l'interface de sortie","Le mot de passe du routeur voisin","Le réseau de destination et son masque"],"g":[1,3],"e":"ip route 10.2.0.0 255.255.0.0 192.168.1.2 indique le réseau, le masque et le prochain saut."},
  {"theme":"vlan","level":"hero","format":"order","q":"Remets dans l'ordre la mise en place d'un nouveau VLAN pour un service :","items":["Créer le VLAN et lui donner un nom","Affecter les ports d'accès et autoriser le VLAN sur les trunks concernés","Configurer la passerelle (SVI ou sous-interface) et le relais DHCP","Tester depuis un poste : adresse obtenue, ping de la passerelle"],"e":"On crée le VLAN, on le rattache aux ports et aux liens inter-commutateurs, on ajoute les services IP, puis on vérifie depuis un poste."},
  {"theme":"vlan","level":"hero","format":"input","q":"Quelle est la distance administrative d'une route statique ?","placeholder":"Valeur","answers":["1"],"e":"Une route statique a une distance administrative de 1, juste après les réseaux directement connectés (0)."},
  {"theme":"vlan","level":"hero","format":"input","q":"Quelle est la distance administrative d'OSPF ?","placeholder":"Valeur","answers":["110"],"e":"OSPF : 110. EIGRP interne : 90, RIP : 120, eBGP : 20."},
  {"theme":"vlan","level":"hero","format":"input","q":"Quel est le numéro du VLAN par défaut sur un commutateur Cisco ?","placeholder":"Numéro","answers":["1","vlan 1"],"e":"Tous les ports sont initialement dans le VLAN 1, qui est aussi souvent le VLAN natif. On le laisse inutilisé par prudence."},
  {"theme":"vlan","level":"hero","format":"input","q":"Quelle commande Cisco affiche la table de routage ?","placeholder":"Commande","answers":["show ip route","sh ip route"],"e":"show ip route liste les routes avec leur origine : C pour connectée, S pour statique, O pour OSPF…"},
  {"theme":"vlan","level":"super","format":"single","q":"À quoi servent HSRP et VRRP ?","a":["À attribuer automatiquement des adresses IP aux postes d'un même VLAN","À offrir une passerelle redondante : deux routeurs partagent une adresse IP virtuelle","À supprimer les boucles de niveau 2 entre les commutateurs redondants","À chiffrer le trafic échangé entre deux routeurs reliés par une liaison redondante"],"g":1,"e":"Les postes utilisent l'adresse virtuelle comme passerelle. Si le routeur actif tombe, l'autre prend le relais sans reconfiguration des postes."},
  {"theme":"vlan","level":"super","format":"single","q":"Que désigne le « root bridge » dans Spanning Tree ?","a":["Le routeur de sortie","Le commutateur le plus rapide","Le premier commutateur allumé","Le commutateur de référence, élu pour le plus petit identifiant de pont, d'où partent les chemins sans boucle"],"g":3,"e":"L'élection tient compte de la priorité puis de l'adresse MAC. On fixe la priorité manuellement pour que ce soit un équipement central et non le plus vieux commutateur."},
  {"theme":"vlan","level":"super","format":"single","q":"Qu'est-ce qu'une attaque de VLAN hopping ?","a":["Passer d'un VLAN à un autre sans routage, par exemple avec une double étiquette 802.1Q ou en négociant un trunk","Saturer la table CAM","Rediriger le DNS","Voler des baux DHCP"],"g":0,"e":"Le VLAN hopping contourne la séparation des VLAN. Il exploite le VLAN natif (double étiquetage) ou la négociation automatique de trunk (DTP)."},
  {"theme":"vlan","level":"super","format":"single","q":"Quelle mesure prévient le VLAN hopping par négociation de trunk ?","a":["Utiliser le VLAN 1 comme VLAN natif sur tous les ports","Augmenter la MTU des interfaces entre commutateurs","Désactiver DTP et fixer les ports en mode access","Activer un Wi-Fi invité séparé sur les points d'accès"],"g":2,"e":"Un port d'accès ne doit jamais négocier un trunk. On fixe le mode et on désactive la négociation (switchport nonegotiate sur les trunks)."},
  {"theme":"vlan","level":"super","format":"single","q":"À quoi sert DHCP snooping ?","a":["À compresser les baux pour économiser de la mémoire sur le commutateur","À répartir la charge entre plusieurs serveurs DHCP, afin qu'aucun d'eux ne soit saturé de requêtes","À n'accepter les réponses DHCP que depuis des ports de confiance, contre les faux serveurs DHCP","À chiffrer les adresses distribuées pour empêcher leur capture sur le réseau"],"g":2,"e":"Un faux serveur DHCP peut distribuer une mauvaise passerelle ou un mauvais DNS. Le snooping bloque ses réponses sur les ports non fiables."},
  {"theme":"vlan","level":"super","format":"single","q":"Que contrôle l'inspection ARP dynamique (DAI) ?","a":["Les mots de passe des ports et des comptes d'administration","La température interne du commutateur et la vitesse de ses ventilateurs","Les VLAN autorisés sur un trunk entre deux commutateurs","La validité des réponses ARP, contre l'usurpation ARP (ARP spoofing)"],"g":3,"e":"DAI vérifie les messages ARP à partir de la base du DHCP snooping et rejette ceux qui annoncent une fausse association adresse IP / adresse MAC."},
  {"theme":"vlan","level":"super","format":"single","q":"À quoi sert la sécurité de port (port security) ?","a":["À limiter les adresses MAC autorisées sur un port","À limiter la vitesse du port","À chiffrer les trames","À sauvegarder la configuration"],"g":0,"e":"On limite le nombre d'adresses MAC ou on fixe les adresses attendues. En cas de violation, le port peut être bloqué ou signaler l'événement."},
  {"theme":"vlan","level":"super","format":"single","q":"Que signifie la lettre « O » devant une ligne de show ip route ?","a":["Route statique","Route apprise par OSPF","Route obsolète","Route par défaut"],"g":1,"e":"Codes courants : C connectée, L locale, S statique, O OSPF, B BGP, * candidate à la route par défaut."},
  {"theme":"vlan","level":"super","format":"single","q":"À quoi sert une route statique flottante ?","a":["À chiffrer le trafic qui emprunte la route principale entre deux sites distants","À répartir la charge à parts égales entre deux routes de même distance administrative","À accélérer le routage : sa distance administrative très basse la rend prioritaire sur toutes les autres routes","À servir de secours : sa distance administrative élevée ne la rend active que si la route préférée disparaît"],"g":3,"e":"Par exemple, une route vers Internet par un lien 4G avec une distance de 200 : elle n'entre dans la table que si la route principale (OSPF 110 ou statique 1) disparaît."},
  {"theme":"vlan","level":"super","format":"single","q":"Comment OSPF choisit-il, par défaut, entre plusieurs chemins ?","a":["Il retient le coût le plus faible, calculé à partir de la bande passante des interfaces","Il retient le chemin qui compte le moins de sauts, quelle que soit la bande passante","Il retient la route apprise le plus récemment par le routeur, car elle est la plus à jour","Il retient le plus court en kilomètres, d'après la position des routeurs"],"g":0,"e":"Le coût est inversement proportionnel à la bande passante. Un chemin à deux liens rapides peut être préféré à un lien direct lent."},
  {"theme":"vlan","level":"super","format":"single","q":"À quoi sert une liste de contrôle d'accès (ACL) appliquée entre des VLAN ?","a":["À changer l'adresse IP des postes qui passent d'un VLAN à un autre","À créer de nouveaux VLAN lorsque le trafic entre deux groupes devient trop important","À filtrer ce qui peut passer d'un VLAN à l'autre, par exemple interdire les invités vers les serveurs","À accélérer les transferts de fichiers entre les VLAN du réseau interne"],"g":2,"e":"Le routage inter-VLAN est l'endroit où l'on applique la politique de sécurité : qui peut joindre quoi, sur quels ports."},
  {"theme":"vlan","level":"super","format":"single","q":"Qu'est-ce qu'EtherChannel (LACP) ?","a":["Un protocole de supervision qui interroge les commutateurs","L'agrégation de plusieurs liens physiques en un seul lien logique","Une redondance de passerelle entre deux routeurs, avec adresse virtuelle","Un trunk chiffré entre deux commutateurs de niveau 3"],"g":1,"e":"Plusieurs liens se comportent comme un seul : plus de débit et de la redondance, sans que Spanning Tree bloque les liens redondants."},
  {"theme":"vlan","level":"super","format":"tf","q":"OSPF envoie des messages Hello pour découvrir ses voisins et maintenir les adjacences.","a":["Vrai","Faux"],"g":0,"e":"Vrai : les Hello sont envoyés régulièrement (10 secondes sur Ethernet). Sans réponse pendant le délai Dead (40 secondes), le voisin est déclaré perdu."},
  {"theme":"vlan","level":"super","format":"tf","q":"L'adresse IP de passerelle utilisée dans HSRP est celle de l'interface physique du routeur actif.","a":["Vrai","Faux"],"g":1,"e":"Faux : c'est l'adresse virtuelle, partagée par les routeurs du groupe. C'est ce qui permet de basculer sans toucher aux postes."},
  {"theme":"vlan","level":"super","format":"multi","q":"Quelles protections limitent les attaques de niveau 2 sur un réseau d'accès ? (plusieurs réponses)","a":["DHCP snooping","Inspection ARP dynamique (DAI)","Un trunk ouvert sur tous les ports","Port security"],"g":[0,1,3],"e":"Ces trois fonctions travaillent ensemble contre faux serveurs DHCP, saturation de la table MAC et usurpation ARP. Un trunk ouvert partout aggrave au contraire la situation."},
  {"theme":"vlan","level":"super","format":"multi","q":"Quelles sources de routes un routeur peut-il utiliser ? (plusieurs réponses)","a":["Les réseaux directement connectés","Les routes statiques","Les protocoles dynamiques comme OSPF","Les adresses MAC des voisins"],"g":[0,1,2],"e":"Un routeur construit sa table à partir des réseaux connectés, des routes configurées et des routes apprises. Les adresses MAC relèvent de la commutation."},
  {"theme":"vlan","level":"super","format":"order","q":"Remets dans l'ordre le choix d'une route par un routeur :","items":["Il cherche les routes qui correspondent à l'adresse de destination","Il retient celle au plus long préfixe","À préfixe égal, il préfère la plus faible distance administrative","À distance égale, il compare les métriques"],"e":"Le préfixe le plus précis l'emporte, puis la confiance en la source (distance administrative), enfin la métrique du protocole."},
  {"theme":"vlan","level":"super","format":"input","q":"Quel protocole propriétaire de Cisco négocie dynamiquement les trunks, et qu'on désactive sur les ports d'accès ? (trois lettres)","placeholder":"Sigle","answers":["DTP"],"e":"DTP (Dynamic Trunking Protocol) peut faire monter un trunk à la demande d'un poste malveillant. On le désactive avec switchport nonegotiate ou en fixant le mode."},
  {"theme":"vlan","level":"super","format":"input","q":"Quelle est la distance administrative d'une route eBGP ?","placeholder":"Valeur","answers":["20"],"e":"eBGP : 20, EIGRP interne : 90, OSPF : 110, RIP : 120, iBGP : 200."},
  {"theme":"vlan","level":"super","format":"input","q":"Quel est l'intervalle par défaut, en secondes, entre deux messages Hello OSPF sur un réseau Ethernet ?","placeholder":"Secondes","answers":["10","10 s","10 secondes"],"e":"Hello toutes les 10 secondes et délai Dead de 40 secondes sur les réseaux de diffusion et point à point. Ces valeurs doivent être identiques entre voisins."},
  {"theme":"vlan","level":"legende","format":"single","q":"Deux routeurs OSPF restent bloqués en état ExStart ou Exchange. Quelle cause est classique ?","a":["Des communautés SNMP différentes sur les deux routeurs","Un VLAN natif identique sur la liaison","Une MTU différente sur les deux interfaces","Le même identifiant de routeur sur les deux équipements"],"g":2,"e":"Les routeurs échangent des descriptions de base de données dont la taille dépend de la MTU. Si elle diffère, l'échange échoue et l'adjacence reste bloquée."},
  {"theme":"vlan","level":"legende","format":"single","q":"Sur un routeur Cisco, quel attribut BGP est comparé en premier dans le processus de décision (avant la préférence locale) ?","a":["L'origine","Le poids (weight), propre à Cisco et local au routeur","Le MED","La longueur du chemin d'AS"],"g":1,"e":"Le poids est un attribut Cisco, non transmis aux voisins. Viennent ensuite la préférence locale, les routes locales, la longueur du chemin d'AS, l'origine et le MED."},
  {"theme":"vlan","level":"legende","format":"single","q":"Quelle est la différence entre eBGP et iBGP ?","a":["eBGP relie des systèmes autonomes différents ; iBGP relie des routeurs d'un même système autonome","iBGP est réservé aux réseaux IPv6, alors qu'eBGP ne gère que l'IPv4","iBGP relie des systèmes autonomes différents ; eBGP relie des routeurs situés dans un même système autonome","eBGP fonctionne en UDP, alors qu'iBGP fonctionne en TCP sur le port 179"],"g":0,"e":"BGP échange des routes entre organisations (eBGP) et les diffuse à l'intérieur de l'AS (iBGP). Les deux utilisent TCP 179."},
  {"theme":"vlan","level":"legende","format":"single","q":"Pourquoi le VLAN natif doit-il être identique aux deux extrémités d'un trunk ?","a":["Sinon le DHCP s'arrête","Sinon les adresses MAC changent","Sinon le trunk chiffre mal","Sinon les trames non étiquetées arrivent dans un autre VLAN, et le protocole STP peut signaler une incohérence"],"g":3,"e":"Les trames natives n'ont pas d'étiquette : chaque extrémité les range dans son propre VLAN natif. Une différence fait fuiter le trafic d'un VLAN dans un autre."},
  {"theme":"vlan","level":"legende","format":"single","q":"Quelle faiblesse exploite une attaque de double étiquetage 802.1Q ?","a":["La table de routage","Le VLAN natif du trunk, qui permet à une trame d'atteindre un autre VLAN","La résolution DNS","La table CAM du commutateur"],"g":1,"e":"L'attaquant place deux étiquettes : la première, celle du VLAN natif, est retirée par le premier commutateur, et la seconde mène la trame dans le VLAN visé. On y répond en utilisant un VLAN natif inutilisé."},
  {"theme":"vlan","level":"legende","format":"single","q":"À quoi sert un VRF sur un routeur ?","a":["À maintenir plusieurs tables de routage indépendantes sur le même équipement","À accélérer le routage statique en désactivant les routes dynamiques de l'équipement","À chiffrer les routes échangées entre deux routeurs voisins du même réseau","À gérer les mots de passe d'accès des administrateurs au routeur"],"g":0,"e":"Les VRF isolent des réseaux qui peuvent même réutiliser les mêmes adresses : clients d'un opérateur, zone d'administration, invités."},
  {"theme":"vlan","level":"legende","format":"single","q":"Pourquoi résumer des routes (route summarization) ?","a":["Chiffrer les annonces de routage échangées entre routeurs voisins","Supprimer les VLAN inutilisés pour libérer de la mémoire sur le routeur","Augmenter la métrique de chaque route pour forcer l'usage du chemin de secours","Réduire la taille des tables de routage et limiter la propagation des changements"],"g":3,"e":"Annoncer 10.1.0.0/16 plutôt que 256 réseaux en /24 allège les tables et cache les changements de détail au reste du réseau."},
  {"theme":"vlan","level":"legende","format":"single","q":"Qu'apporte BFD à un protocole de routage ?","a":["Le résumé automatique de routes aux frontières de réseau","L'authentification des utilisateurs sur chaque lien","Une détection très rapide de la panne d'un lien","Le chiffrement des annonces entre les routeurs voisins"],"g":2,"e":"BFD (Bidirectional Forwarding Detection) envoie des messages très fréquents. Il détecte une panne en une fraction de seconde, bien plus vite que les temporisateurs des protocoles de routage."},
  {"theme":"vlan","level":"legende","format":"single","q":"Un poste reçoit son VLAN dynamiquement selon son identité grâce à 802.1X. Quel serveur renvoie l'attribut de VLAN ?","a":["Le serveur DNS","Le serveur DHCP","Le serveur NTP","Le serveur RADIUS"],"g":3,"e":"Le serveur RADIUS authentifie le poste ou l'utilisateur et renvoie dans sa réponse le VLAN à utiliser. Le port est alors placé automatiquement dans le bon réseau."},
  {"theme":"vlan","level":"legende","format":"single","q":"Combien de segments logiques VXLAN peut-il identifier avec son identifiant (VNI) ?","a":["Environ 16 millions (24 bits)","4 094","256","65 536"],"g":0,"e":"Le VNI de VXLAN est codé sur 24 bits, contre 12 bits pour l'identifiant de VLAN 802.1Q. Il répond aux besoins des centres de données de grande taille."},
  {"theme":"vlan","level":"legende","format":"tf","q":"Sur un commutateur de niveau 3 Cisco, créer des SVI pour deux VLAN suffit pour que leurs postes communiquent, même sans la commande ip routing.","a":["Vrai","Faux"],"g":1,"e":"Faux : sans ip routing, le commutateur traite ses SVI comme de simples interfaces de gestion et ne route pas entre elles. Il faut activer ip routing (et que les SVI soient up/up)."},
  {"theme":"vlan","level":"legende","format":"multi","q":"Quelles mesures durcissent un trunk 802.1Q ? (plusieurs réponses)","a":["Laisser tous les VLAN autorisés par défaut","Désactiver la négociation DTP","Utiliser un VLAN natif inutilisé","Limiter les VLAN autorisés"],"g":[1,2,3],"e":"On limite la surface (VLAN autorisés), on évite le double étiquetage (VLAN natif inutilisé) et on interdit la négociation. Tout autoriser est précisément ce qu'il faut éviter."},
  {"theme":"vlan","level":"legende","format":"multi","q":"Quelles causes empêchent une adjacence OSPF de se former ? (plusieurs réponses)","a":["Des couleurs de câble différentes","Des temporisateurs Hello et Dead différents","Des zones OSPF différentes sur le lien","Des noms d'hôte différents"],"g":[1,2],"e":"Les voisins doivent s'accorder sur la zone, les temporisateurs, le type de réseau et l'authentification. Le nom d'hôte est sans importance."},
  {"theme":"vlan","level":"legende","format":"multi","q":"Quels éléments un routeur compare-t-il entre deux routes de même préfixe vers une destination ? (plusieurs réponses)","a":["Le nom de l'interface","L'heure d'ajout de la route","La distance administrative","La métrique du protocole"],"g":[2,3],"e":"À préfixe égal, il compare la fiabilité de la source (distance administrative) puis la métrique du protocole. Le nom de l'interface n'entre pas en compte."},
  {"theme":"vlan","level":"legende","format":"order","q":"Remets dans l'ordre le dépannage d'un VLAN qui n'a plus de connectivité entre deux sites :","items":["Vérifier que le VLAN existe et est actif sur chaque commutateur","Vérifier les ports d'accès et les trunks (VLAN autorisés, VLAN natif)","Vérifier la passerelle (SVI) et le routage","Contrôler les ACL et les règles de pare-feu"],"e":"On remonte du plus bas niveau (VLAN, liens) au plus haut (routage, filtrage)."},
  {"theme":"vlan","level":"legende","format":"input","q":"Quelle est la distance administrative de RIP ?","placeholder":"Valeur","answers":["120"],"e":"RIP : 120. Il est ancien mais encore rencontré dans de petits réseaux."},
  {"theme":"vlan","level":"legende","format":"input","q":"Quelle est la distance administrative d'EIGRP pour les routes internes ?","placeholder":"Valeur","answers":["90"],"e":"EIGRP interne : 90, EIGRP externe : 170."},
  {"theme":"vlan","level":"legende","format":"input","q":"Quelle est la distance administrative d'iBGP ?","placeholder":"Valeur","answers":["200"],"e":"iBGP : 200, contre 20 pour eBGP. Une route apprise d'un autre AS est ainsi préférée à une route de l'AS interne."},
  {"theme":"vlan","level":"legende","format":"input","q":"Quelle commande Cisco active le routage IP sur un commutateur de niveau 3 ?","placeholder":"Commande","answers":["ip routing"],"e":"Sans ip routing, un commutateur de niveau 3 ne route pas : ses SVI existent mais ne transmettent pas de trafic entre VLAN."},
  {"theme":"vlan","level":"legende","format":"input","q":"Quelle commande Cisco affiche l'état des trunks, avec leurs VLAN autorisés et leur VLAN natif ?","placeholder":"Commande","answers":["show interfaces trunk","show int trunk","show interface trunk","sh int trunk","sh interfaces trunk"],"e":"show interfaces trunk indique les ports en trunk, leur encapsulation, leur VLAN natif et la liste des VLAN autorisés et actifs."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Que fait la commande ping ?","a":["Elle liste les ports ouverts d'une machine distante et les services qui y écoutent","Elle vide le cache DNS du poste et renouvelle le bail DHCP","Elle affiche les routes connues du poste et leur métrique","Elle envoie des messages ICMP à une machine et mesure le temps de réponse"],"g":3,"e":"ping envoie des demandes d'écho ICMP et attend les réponses. On y lit la latence et les pertes éventuelles."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Quelle commande Windows affiche l'adresse IP, le masque et la passerelle du poste ?","a":["tracert","ping","ipconfig","nslookup"],"g":2,"e":"ipconfig affiche la configuration IP de chaque carte réseau. Avec /all, on obtient aussi l'adresse MAC, le serveur DHCP et les serveurs DNS."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Que signifie une adresse en 169.254.x.x sur un poste ?","a":["L'adresse a été réservée sur le serveur DHCP par l'administrateur pour ce poste","Le poste n'a pas obtenu d'adresse par DHCP et s'est attribué une adresse automatique (APIPA)","Le poste est connecté en VPN et l'adresse vient de la passerelle du tunnel","Le poste est connecté à Internet et utilise une adresse publique attribuée par le FAI"],"g":1,"e":"Quand aucun serveur DHCP ne répond, Windows s'attribue une adresse 169.254.x.x qui ne permet de communiquer qu'avec le réseau local immédiat. Il faut chercher du côté du DHCP ou du câble."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Que représente le TTL dans une réponse de ping ?","a":["Le nombre de routeurs que le paquet peut encore traverser avant d'être détruit","La durée de vie en secondes de la réponse, avant qu'elle ne soit supprimée du cache","Le débit maximal de la liaison utilisée pour envoyer le paquet","La durée en secondes que le paquet met pour aller et revenir"],"g":0,"e":"Chaque routeur retire 1 au TTL. Arrivé à 0, le paquet est détruit : cela évite que des paquets tournent indéfiniment."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Un utilisateur n'a plus accès à rien. Que vérifier en premier ?","a":["Le câble ou le Wi-Fi : le poste est-il physiquement connecté au réseau ?","Le certificat du serveur web interne, qui peut avoir expiré ou être invalide","La version d'Office installée sur le poste de l'utilisateur","Le fond d'écran et les paramètres d'affichage du bureau"],"g":0,"e":"On commence par le plus simple : voyant du port, câble, Wi-Fi activé. Inutile de regarder le DNS ou les applications si le poste n'est pas relié au réseau."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Quelle commande Windows demande un nouveau bail DHCP ?","a":["ipconfig /flushdns","ipconfig /displaydns","ipconfig /renew","ipconfig /showclassid"],"g":2,"e":"ipconfig /release abandonne l'adresse actuelle et ipconfig /renew en demande une nouvelle au serveur DHCP."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Quelle commande Windows affiche le chemin suivi par les paquets jusqu'à une destination ?","a":["ping","nslookup","arp","tracert"],"g":3,"e":"tracert liste les routeurs traversés (les sauts) avec leur temps de réponse. Il aide à repérer où le trajet se bloque."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Que signifie « Délai d'attente de la demande dépassé » lors d'un ping ?","a":["Le câble est trop long : le signal est atténué avant d'atteindre la machine","Aucune réponse n'est arrivée dans le délai : la machine est éteinte, injoignable, ou elle filtre le ping","Le DNS est en panne : le nom de la machine ne peut pas être résolu en adresse IP","La machine est en train de s'éteindre et ne peut plus répondre aux requêtes"],"g":1,"e":"Un délai dépassé ne dit pas pourquoi. Une machine peut être allumée et refuser de répondre à l'ICMP à cause de son pare-feu."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Pourquoi tester d'abord un ping vers la passerelle, puis vers un site externe ?","a":["Pour installer automatiquement les mises à jour de sécurité sur la passerelle et le poste","Pour vider le cache du navigateur avant chaque test de connexion","Pour savoir où se situe la panne : réseau local, sortie vers Internet ou DNS","Pour changer de passerelle si la première ne répond plus"],"g":2,"e":"Chaque test élimine une partie du chemin : poste, réseau local, passerelle, Internet, puis nom de domaine."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Quelle commande affiche l'adresse MAC (adresse physique) de la carte réseau sous Windows ?","a":["ping -a","tracert -m","ipconfig","ipconfig /all"],"g":3,"e":"ipconfig /all affiche pour chaque carte son adresse physique, l'état du DHCP, la passerelle et les serveurs DNS."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Un site s'ouvre depuis un téléphone en 4G, mais pas depuis le réseau de l'entreprise. Que suspecter ?","a":["Un élément propre au réseau de l'entreprise (DNS, pare-feu, proxy, filtrage)","Un problème de licence Microsoft 365","Un problème sur le site lui-même","Un problème sur le téléphone"],"g":0,"e":"Si le site répond ailleurs, il fonctionne. La différence vient du chemin : DNS interne, filtrage web, pare-feu, proxy."},
  {"theme":"diagnostic","level":"recrue","format":"single","q":"Quelle est une bonne méthode de dépannage réseau ?","a":["Commencer par réinstaller le système du poste, puis vérifier les câbles et l'adresse IP","Partir du plus simple (câble, adresse IP) vers le plus complexe (DNS, application), un changement à la fois","Tout redémarrer en même temps (poste, commutateur et routeur), puis tester si le problème a disparu","Modifier plusieurs réglages à la fois avant de tester, pour gagner du temps sur le dépannage"],"g":1,"e":"Modifier une chose à la fois permet de savoir ce qui a réglé le problème, ou ce qui l'a aggravé."},
  {"theme":"diagnostic","level":"recrue","format":"tf","q":"Un ping réussi vers la passerelle prouve que le poste communique avec son réseau local.","a":["Vrai","Faux"],"g":0,"e":"Vrai : la passerelle fait partie du réseau local. Un ping qui réussit montre que la carte, l'adresse IP et la liaison fonctionnent."},
  {"theme":"diagnostic","level":"recrue","format":"tf","q":"Un ping qui échoue prouve toujours que la machine est éteinte.","a":["Vrai","Faux"],"g":1,"e":"Faux : beaucoup de pare-feu bloquent l'ICMP. La machine peut fonctionner normalement, et ses services répondre."},
  {"theme":"diagnostic","level":"recrue","format":"tf","q":"Une adresse en 169.254.x.x est attribuée par le serveur DHCP.","a":["Vrai","Faux"],"g":1,"e":"Faux : c'est le poste lui-même qui se l'attribue quand le DHCP ne répond pas (APIPA)."},
  {"theme":"diagnostic","level":"recrue","format":"multi","q":"Quelles commandes aident à diagnostiquer un problème réseau sous Windows ? (plusieurs réponses)","a":["tracert","chkdsk","diskpart","ping"],"g":[0,3],"e":"ping et tracert testent la communication. chkdsk et diskpart concernent les disques."},
  {"theme":"diagnostic","level":"recrue","format":"multi","q":"Quelles informations affiche ipconfig /all ? (plusieurs réponses)","a":["La liste des utilisateurs connectés","L'adresse MAC de la carte","Le mot de passe Wi-Fi","Les serveurs DNS utilisés"],"g":[1,3],"e":"ipconfig /all détaille la configuration réseau de chaque carte : adresse physique, DHCP, passerelle, serveurs DNS. Il ne montre ni mot de passe ni comptes."},
  {"theme":"diagnostic","level":"recrue","format":"order","q":"Remets dans l'ordre un diagnostic de « pas d'Internet » sur un poste :","items":["Vérifier le câble ou la connexion Wi-Fi","Contrôler l'adresse IP avec ipconfig","Tester la passerelle avec ping","Tester un nom de domaine (résolution DNS)"],"e":"On remonte du matériel vers l'application : lien, adresse IP, passerelle, puis nom."},
  {"theme":"diagnostic","level":"recrue","format":"input","q":"Quelle adresse IPv4 désigne la machine locale (boucle locale) ?","placeholder":"Adresse IP","answers":["127.0.0.1"],"e":"127.0.0.1 permet de tester la pile réseau du poste, sans passer par la carte. Son nom habituel est localhost."},
  {"theme":"diagnostic","level":"recrue","format":"input","q":"Quelle commande Windows affiche le nom de la machine ?","placeholder":"Commande","answers":["hostname"],"e":"hostname affiche le nom d'hôte de l'ordinateur, sans option."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Que signifie une ligne « * * * » dans un tracert ?","a":["Le paquet a été chiffré par le routeur et ne peut plus être lu","La destination est atteinte mais ne répond pas aux requêtes ICMP","Le saut est définitivement en panne et le trafic ne peut plus traverser ce routeur","Aucune réponse à ce saut : le routeur filtre ou ne répond pas à ces messages"],"g":3,"e":"Certains routeurs ne répondent pas aux messages de temps dépassé. Si les sauts suivants répondent, le trafic passe malgré tout."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quelle commande Linux moderne affiche les sockets en écoute avec les processus associés ?","a":["free -m","ip route show","ss -tulpn","lsblk -f"],"g":2,"e":"ss remplace netstat sur les distributions récentes. -t TCP, -u UDP, -l en écoute, -p processus, -n sans résolution de noms."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Comment retrouver le programme associé à un PID relevé avec netstat ?","a":["Avec ipconfig /all, qui liste les processus associés à chaque adresse","Avec tasklist /fi \"pid eq 1234\" ou le Gestionnaire des tâches","Avec tracert 1234, qui affiche le processus du PID indiqué","Avec nslookup 1234, qui renvoie le nom du programme concerné"],"g":1,"e":"Le PID identifie le processus. tasklist ou l'onglet Détails du Gestionnaire des tâches donnent son nom."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quelle commande PowerShell teste la connexion TCP vers le port 443 d'un serveur ?","a":["Test-NetConnection serveur -Port 443","Get-NetIPAddress serveur 443","Test-Connection serveur -Count 443","Resolve-DnsName serveur -Port 443"],"g":0,"e":"Test-NetConnection vérifie la résolution du nom, le ping et l'ouverture du port TCP demandé. Test-Connection est l'équivalent de ping, -Count fixant le nombre d'essais."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Un ping vers un serveur échoue, mais le port 443 répond. Pourquoi ?","a":["Le port 443 est un port ICMP réservé aux requêtes d'écho du ping","Le DNS est en panne pour le ping mais fonctionne pour les connexions HTTPS","Le serveur ou un pare-feu bloque l'ICMP tout en laissant passer HTTPS","Le serveur est éteint, mais un équipement répond à sa place sur le port 443"],"g":2,"e":"Un ping échoué ne prouve pas qu'un service est indisponible. Il faut tester le port du service réellement utilisé."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Que suggère un TTL de 128 dans une réponse de ping ?","a":["Une machine Linux probablement, à plus de 100 sauts (la valeur initiale courante est 64)","Une machine sous Windows probablement, à peu de sauts (la valeur initiale courante est 128)","128 paquets perdus (le TTL compte les paquets non reçus)","Une latence de 128 ms (la valeur du TTL correspond au délai de réponse)"],"g":1,"e":"Windows envoie ses paquets avec un TTL de 128, Linux et macOS avec 64. Le TTL reçu est cette valeur moins le nombre de routeurs traversés."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quelle commande Windows affiche le cache ARP, c'est-à-dire les correspondances adresse IP et adresse MAC ?","a":["arp -a","ipconfig /arp","netstat -a","arp -s"],"g":0,"e":"arp -a liste les voisins connus du poste. On y repère par exemple deux adresses IP qui partagent la même adresse MAC."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quelle option de ping sous Windows envoie des requêtes jusqu'à interruption par Ctrl + C ?","a":["ping -f","ping -a","ping -n","ping -t"],"g":3,"e":"ping -t est utile pour surveiller une liaison pendant qu'on intervient (rebranchement, redémarrage). -n fixe le nombre d'essais."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Dans ipconfig /all, quelle ligne indique que l'adresse IP est fournie par un serveur DHCP ?","a":["DHCP activé : Oui","Suffixe DNS principal","Adresse physique","Passerelle par défaut"],"g":0,"e":"Avec DHCP activé, on trouve aussi l'adresse du serveur DHCP et les dates d'obtention et d'expiration du bail."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quelle cmdlet PowerShell se rapproche le plus d'ipconfig ?","a":["Get-NetFirewallRule","Get-NetIPConfiguration","Get-NetRoute","Get-DnsClientCache"],"g":1,"e":"Get-NetIPConfiguration résume interfaces, adresses, passerelles et serveurs DNS. Get-NetIPAddress détaille les adresses."},
  {"theme":"diagnostic","level":"hero","format":"single","q":"Quel filtre Wireshark n'affiche que les paquets liés à l'adresse 192.168.1.10 ?","a":["host=192.168.1.10","filter ip 192.168.1.10","ip.addr == 192.168.1.10","show 192.168.1.10"],"g":2,"e":"ip.addr == adresse affiche les paquets où l'adresse est source ou destination. ip.src et ip.dst précisent le sens."},
  {"theme":"diagnostic","level":"hero","format":"tf","q":"Un ping peut échouer alors que la machine fonctionne parfaitement.","a":["Vrai","Faux"],"g":0,"e":"Vrai : l'ICMP est souvent filtré par le pare-feu local ou par le réseau. L'absence de réponse n'est donc pas une preuve de panne."},
  {"theme":"diagnostic","level":"hero","format":"tf","q":"Sous Windows, tracert envoie par défaut des paquets TCP SYN.","a":["Vrai","Faux"],"g":1,"e":"Faux : tracert envoie des demandes d'écho ICMP avec un TTL croissant. Sous Linux, traceroute utilise par défaut de l'UDP."},
  {"theme":"diagnostic","level":"hero","format":"multi","q":"Quelles commandes affichent des informations sur les ports ou les connexions ? (plusieurs réponses)","a":["hostname","netstat -an","Get-NetTCPConnection","ipconfig /release"],"g":[1,2],"e":"netstat et Get-NetTCPConnection listent connexions et ports en écoute. ipconfig /release abandonne le bail DHCP et hostname affiche le nom de la machine."},
  {"theme":"diagnostic","level":"hero","format":"multi","q":"Quels signes évoquent un problème DNS plutôt qu'un problème de connexion ? (plusieurs réponses)","a":["Le ping par adresse IP fonctionne, pas le ping par nom","Le voyant du port réseau est éteint","nslookup renvoie une erreur de résolution","L'adresse du poste est en 169.254.x.x"],"g":[0,2],"e":"Si la communication fonctionne par adresse mais pas par nom, c'est la résolution qui est en cause. Un voyant éteint ou une adresse APIPA relèvent de la connexion elle-même."},
  {"theme":"diagnostic","level":"hero","format":"order","q":"Remets dans l'ordre le dépannage de l'accès à une application web interne :","items":["Tester le ping vers le serveur","Vérifier la résolution du nom avec nslookup","Tester le port de l'application","Consulter les journaux du serveur et du pare-feu"],"e":"On valide d'abord la communication, puis le nom, puis le port, avant d'aller lire les journaux côté serveur et pare-feu."},
  {"theme":"diagnostic","level":"hero","format":"input","q":"Quelle option de tracert désactive la résolution des noms (plus rapide) ?","placeholder":"Option","answers":["-d","tracert -d"],"e":"tracert -d affiche seulement les adresses IP, sans interroger le DNS pour chaque saut. Le résultat arrive nettement plus vite."},
  {"theme":"diagnostic","level":"hero","format":"input","q":"Quelle est la valeur initiale courante du TTL des paquets émis par un système Linux ?","placeholder":"Valeur","answers":["64"],"e":"Linux et macOS utilisent un TTL initial de 64 ; Windows 128."},
  {"theme":"diagnostic","level":"hero","format":"input","q":"Quelle option de ping sous Windows fixe le nombre de requêtes envoyées ?","placeholder":"Option","answers":["-n","ping -n"],"e":"ping -n 10 serveur envoie dix requêtes puis s'arrête. Sous Linux, l'option équivalente est -c."},
  {"theme":"diagnostic","level":"hero","format":"input","q":"Quel logiciel libre très répandu permet de capturer et d'analyser les paquets d'un réseau ?","placeholder":"Nom du logiciel","answers":["Wireshark"],"e":"Wireshark capture le trafic réseau et le décode protocole par protocole, avec des filtres puissants."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quel filtre Wireshark affiche les requêtes et réponses DNS ?","a":["tcp.syn","dns","ip.proto == 80","dnsonly"],"g":1,"e":"Il suffit de taper le nom du protocole : dns, http, tls, arp… Wireshark connaît les champs de chacun."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Comment reconnaît-on l'établissement d'une connexion TCP dans une capture ?","a":["SYN, puis SYN-ACK, puis ACK","FIN, puis SYN-ACK, puis ACK","SYN, puis RST, puis ACK","ACK, puis SYN, puis FIN"],"g":0,"e":"C'est la poignée de main en trois temps. Voir le SYN-ACK prouve que le serveur écoute et que le chemin aller-retour fonctionne."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Que signifie un RST reçu immédiatement en réponse à un SYN ?","a":["Le certificat du serveur est expiré et la connexion est refusée","Le service est simplement lent à répondre aux nouvelles demandes de connexion","Le port est fermé : la machine répond qu'aucun service n'y écoute","Le port est filtré par un pare-feu qui rejette silencieusement les paquets"],"g":2,"e":"Un RST rapide vient de la machine cible : le réseau fonctionne, mais aucun service n'écoute sur ce port. Un pare-feu qui ignore le paquet ne répond rien."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Un SYN reste sans aucune réponse, ni SYN-ACK ni RST. Que suspecter ?","a":["Un port fermé sur le serveur, qui renvoie un RST à chaque tentative","Une MTU trop grande qui fragmente les paquets","Un certificat invalide qui interrompt la connexion TLS","Un pare-feu qui ignore les paquets (DROP) ou un problème de routage"],"g":3,"e":"Un port fermé répond par un RST. L'absence totale de réponse indique en général un filtrage silencieux ou un paquet qui n'arrive jamais."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quelle commande Windows teste la MTU d'un chemin ?","a":["ping -f -l 1472 destination","ping -t -l 1472 destination","tracert -h 1472 destination","netsh mtu 1472 destination"],"g":0,"e":"-f interdit la fragmentation et -l fixe la taille des données. 1472 octets + 28 d'en-têtes = 1500 : si la requête passe, la MTU de 1500 est respectée."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quelle commande Linux capture les requêtes DNS sur l'interface eth0, sans résoudre les noms ?","a":["tshark -a dns","tcpdump -i eth0 -nn port 53","tcpdump eth0 dns -r","tcpdump -w port 53 eth0"],"g":1,"e":"-i choisit l'interface, -nn évite la résolution des noms et des ports, et « port 53 » est le filtre de capture."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Que fait « curl -I https://exemple.fr » ?","a":["Il envoie un ping ICMP vers l'adresse du serveur web","Il ignore les certificats invalides et continue la connexion","Il récupère seulement les en-têtes de la réponse HTTP","Il télécharge le site complet avec ses images et ses scripts"],"g":2,"e":"-I envoie une requête HEAD : on voit le code de réponse, les redirections et les en-têtes, sans le contenu."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quel outil teste la négociation TLS d'un serveur et affiche son certificat ?","a":["ssh -p 443 serveur","openssl req -connect serveur:443","telnet serveur 443 -tls","openssl s_client -connect serveur:443"],"g":3,"e":"openssl s_client ouvre une connexion TLS et affiche la chaîne de certificats et les paramètres négociés."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Que révèle une rafale de retransmissions TCP dans une capture ?","a":["De la perte de paquets ou de la congestion sur le chemin","Une imprimante mal installée sur le poste de capture","Un certificat expiré qui interrompt la négociation TLS","Un serveur DNS en panne qui empêche la résolution de tous les noms"],"g":0,"e":"TCP retransmet les segments non acquittés. Beaucoup de retransmissions signalent des pertes sur le chemin ou un lien saturé."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Pourquoi capturer sur un port miroir (SPAN) du commutateur ?","a":["Pour créer un VLAN dédié aux outils d'analyse du réseau","Pour accélérer le port en y dupliquant les trames reçues","Pour chiffrer le trafic qui circule entre les deux commutateurs","Pour voir le trafic d'un autre port sans perturber la liaison"],"g":3,"e":"Le commutateur recopie le trafic du port observé vers le port où est branché l'analyseur. Sans cela, on ne voit que son propre trafic."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quelle commande PowerShell affiche les connexions TCP avec l'identifiant du processus propriétaire ?","a":["Get-DnsClientServerAddress","Get-NetAdapter","Get-NetTCPConnection","Get-NetNeighbor"],"g":2,"e":"Get-NetTCPConnection donne l'état, les adresses et le OwningProcess de chaque connexion. Get-Process permet ensuite de retrouver son nom."},
  {"theme":"diagnostic","level":"super","format":"single","q":"Quel outil combine ping et traceroute pour mesurer la perte à chaque saut ?","a":["nslookup","mtr sous Linux, pathping sous Windows","netstat","arp"],"g":1,"e":"mtr et pathping envoient des sondes en continu et calculent les pertes et la latence saut par saut."},
  {"theme":"diagnostic","level":"super","format":"tf","q":"Une perte observée sur un saut intermédiaire d'un traceroute, sans perte au dernier saut, ne traduit pas forcément un problème réel.","a":["Vrai","Faux"],"g":0,"e":"Vrai : de nombreux routeurs limitent leurs réponses ICMP. Ce qui compte est la perte au saut final et celle qui se poursuit sur les sauts suivants."},
  {"theme":"diagnostic","level":"super","format":"tf","q":"Un RST reçu en réponse à un SYN signifie que le port est ouvert.","a":["Vrai","Faux"],"g":1,"e":"Faux : un RST répond à un SYN quand aucun service n'écoute. Un port ouvert répond par un SYN-ACK."},
  {"theme":"diagnostic","level":"super","format":"multi","q":"Quels outils permettent de capturer des paquets ? (plusieurs réponses)","a":["Wireshark","ipconfig","nslookup","tcpdump"],"g":[0,3],"e":"Wireshark et tcpdump capturent le trafic. nslookup interroge le DNS et ipconfig affiche la configuration IP."},
  {"theme":"diagnostic","level":"super","format":"multi","q":"Quels symptômes évoquent une MTU trop grande sur un chemin ? (plusieurs réponses)","a":["Un message « mot de passe expiré »","Des NXDOMAIN fréquents","Des pages qui se figent en cours de chargement","Le ping de petits paquets passe, pas celui de gros paquets non fragmentables"],"g":[2,3],"e":"Les petits paquets traversent le chemin, les gros sont perdus. Le résultat : des pages qui chargent à moitié et des connexions TLS qui se figent."},
  {"theme":"diagnostic","level":"super","format":"order","q":"Remets dans l'ordre l'analyse d'une capture lors d'une connexion qui échoue :","items":["Filtrer sur l'adresse IP et le port concernés","Chercher l'établissement TCP (SYN, SYN-ACK, ACK)","Examiner la suite (négociation TLS, requêtes HTTP, erreurs)","Conclure : serveur, pare-feu, réseau ou application"],"e":"On isole la conversation, on vérifie le transport, puis on regarde la couche application avant de conclure."},
  {"theme":"diagnostic","level":"super","format":"input","q":"Quel filtre Wireshark isole le trafic TCP à destination ou en provenance du port 443 ?","placeholder":"Filtre","answers":["tcp.port == 443","tcp.port==443"],"e":"tcp.port == 443 sélectionne les paquets dont l'un des ports est 443. tcp.dstport et tcp.srcport précisent le sens."},
  {"theme":"diagnostic","level":"super","format":"input","q":"Quel indicateur TCP marque la demande d'ouverture d'une connexion ? (trois lettres)","placeholder":"Indicateur","answers":["SYN"],"e":"Le SYN (synchronize) ouvre la connexion. Le serveur répond par SYN-ACK et le client termine par un ACK."},
  {"theme":"diagnostic","level":"super","format":"input","q":"Quelle option de curl affiche le détail de la connexion et des échanges ?","placeholder":"Option","answers":["-v","curl -v","--verbose"],"e":"curl -v montre la résolution, la connexion, la négociation TLS et les en-têtes échangés. C'est le premier réflexe pour diagnostiquer une requête web."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Quel message ICMP signale qu'un paquet est trop gros et qu'il ne peut pas être fragmenté ?","a":["Type 11, code 0 : temps dépassé, le paquet a été détruit avant son arrivée","Type 5 : redirection, envoyée quand un meilleur routeur existe","Type 8 : demande d'écho, envoyée quand le paquet est trop gros","Type 3, code 4 : destination injoignable, fragmentation nécessaire"],"g":3,"e":"Ce message permet la découverte de la MTU du chemin (PMTUD). S'il est filtré, les connexions échouent avec de gros paquets : c'est le cas du « trou noir PMTUD »."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Dans un tracert, un routeur intermédiaire affiche 80 % de perte, mais la destination 0 %. Que conclure ?","a":["La liaison finale est défectueuse : le routeur perd 80 % des paquets qui le traversent vers le serveur","Probablement un routeur qui limite ses réponses ICMP : le trafic qui le traverse n'est pas touché","Le DNS est en cause : le routeur ne peut pas résoudre le nom des sauts","Le serveur de destination est lent et ne répond pas à toutes les requêtes"],"g":1,"e":"Un routeur traite en priorité le trafic qu'il transmet, et répond avec parcimonie aux sondes. Une perte qui n'apparaît pas aux sauts suivants n'est pas réelle."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Que signifie une fenêtre TCP à zéro (zero window) dans une capture ?","a":["Le récepteur ne peut plus recevoir de données : il est saturé ou lent à lire","Le paquet reçu est corrompu et doit être retransmis par l'émetteur","Le pare-feu bloque le port et rejette les nouveaux paquets entrants","La connexion est fermée normalement par l'un des deux interlocuteurs"],"g":0,"e":"Le récepteur annonce 0 octet de fenêtre pour dire à l'émetteur de patienter. L'application qui lit les données est souvent en cause, pas le réseau."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"À chaque requête, une réponse DNS arrive après environ 2 secondes. Que suspecter ?","a":["Un câble trop long qui ajoute un délai fixe à chaque paquet envoyé","Un certificat expiré sur le serveur DNS, qui retarde la négociation de chaque requête","Un premier serveur DNS qui ne répond pas, avant le basculement vers le suivant","Une MTU insuffisante qui fragmente chaque requête avant son envoi"],"g":2,"e":"Le client attend un délai (environ 1 à 2 secondes) avant d'essayer le serveur DNS suivant. Un serveur mort en tête de liste ralentit toute la navigation."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Un compteur d'erreurs CRC élevé sur un port de commutateur évoque surtout…","a":["Un problème physique : câble ou connecteur défectueux, carte réseau en cause, ou désaccord de duplex","Un bail DHCP expiré, qui oblige le poste à renégocier son adresse IP à chaque trame","Un serveur DNS lent, qui retarde la résolution des noms pour tous les postes du réseau","Un VLAN mal configuré sur le port, qui rejette les trames d'un autre réseau"],"g":0,"e":"Les erreurs CRC indiquent des trames corrompues à la réception. On change le câble, on teste un autre port et on vérifie la vitesse et le duplex."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Quelle est la conséquence d'une discordance de duplex entre un poste et un commutateur ?","a":["Un blocage du VLAN natif sur le trunk entre les deux commutateurs voisins","Un refus d'authentification 802.1X par le serveur RADIUS du réseau","Des collisions tardives, des erreurs et des performances très dégradées","Une perte de la résolution DNS pour les noms internes"],"g":2,"e":"Un côté en full duplex et l'autre en half duplex provoque des collisions que le full duplex ne sait pas gérer. Le lien « marche » mais très mal. Le remède est de laisser les deux côtés en négociation automatique."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Quel filtre Wireshark isole les retransmissions détectées par l'analyse TCP ?","a":["tcp.lost","tcp.analysis.retransmission","ip.retransmit","tcp.retry"],"g":1,"e":"Wireshark analyse les flux TCP et marque retransmissions, ACK dupliqués, fenêtres nulles… tcp.analysis.flags les regroupe."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Quelle commande Windows enregistre une capture réseau sans installer Wireshark ?","a":["ipconfig /capture","tracert -w","netstat -c","netsh trace start capture=yes (ou pktmon)"],"g":3,"e":"netsh trace crée une trace .etl, qu'on peut ouvrir avec Message Analyzer ou convertir pour Wireshark. pktmon, plus récent, fait de même."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Un transfert de gros fichiers est lent sur une liaison à forte latence, alors que le débit de la ligne est correct. Quel facteur limite une connexion TCP unique ?","a":["Le TTL des paquets","L'adresse MAC du serveur","Le nombre de VLAN","La taille de la fenêtre TCP et le temps d'aller-retour : débit maximal ≈ fenêtre ÷ latence"],"g":3,"e":"Avec une fenêtre de 64 Ko et 100 ms d'aller-retour, le débit plafonne à environ 5 Mbit/s. L'ajustement de la fenêtre, ou plusieurs connexions en parallèle, améliore la situation."},
  {"theme":"diagnostic","level":"legende","format":"single","q":"Quel est l'intérêt de mtr par rapport à traceroute ?","a":["Il combine route et statistiques de perte et de latence, mesurées en continu sur chaque saut","Il capture le contenu des paquets de chaque saut pour les analyser ensuite","Il remplace le DNS en résolvant lui-même les noms de chaque saut","Il chiffre les paquets échangés entre les sauts pour éviter leur interception"],"g":0,"e":"traceroute ne fait qu'un passage. mtr répète les sondes et affiche pertes, moyenne et gigue par saut, ce qui permet de distinguer un vrai problème d'une simple limitation ICMP."},
  {"theme":"diagnostic","level":"legende","format":"tf","q":"Un paquet dont le TTL arrive à 1 sur un routeur est détruit par celui-ci, qui renvoie un message ICMP « temps dépassé ».","a":["Vrai","Faux"],"g":0,"e":"Vrai : le routeur décrémente le TTL, obtient 0 et détruit le paquet en prévenant l'émetteur. C'est ce mécanisme que traceroute exploite pour découvrir les sauts."},
  {"theme":"diagnostic","level":"legende","format":"multi","q":"Quelles causes expliquent des retransmissions TCP en rafale ? (plusieurs réponses)","a":["Un câble ou un connecteur défectueux","Une perte de paquets sur le chemin","Un nom DNS inexistant","La congestion d'une liaison"],"g":[0,1,3],"e":"Les retransmissions viennent de paquets perdus ou retardés. Un nom DNS inexistant empêche en revanche toute connexion."},
  {"theme":"diagnostic","level":"legende","format":"multi","q":"Quels éléments valider pour écarter un problème de couche 2 ? (plusieurs réponses)","a":["Les compteurs d'erreurs (CRC) du port","La version du navigateur","Le VLAN auquel le port est affecté","L'état du lien et le duplex"],"g":[0,2,3],"e":"La couche 2 concerne le lien, les erreurs de trames et les VLAN. Le navigateur appartient à la couche application."},
  {"theme":"diagnostic","level":"legende","format":"multi","q":"Quels outils permettent de rechercher des pertes sur un chemin ? (plusieurs réponses)","a":["Un ping prolongé","nslookup","mtr","pathping"],"g":[0,2,3],"e":"ping, pathping et mtr mesurent pertes et latence. nslookup ne teste que la résolution des noms."},
  {"theme":"diagnostic","level":"legende","format":"order","q":"Remets dans l'ordre un dépannage réseau selon les couches du modèle OSI, du bas vers le haut :","items":["Couche physique : câble, voyant, lien","Couche liaison : VLAN, adresse MAC, duplex","Couche réseau : adresse IP, passerelle, routage","Couche application : DNS, port, service"],"e":"Une panne basse masque toutes celles du dessus. On valide chaque couche avant de passer à la suivante."},
  {"theme":"diagnostic","level":"legende","format":"input","q":"Quelle commande Windows combine ping et tracert pour mesurer les pertes à chaque saut ?","placeholder":"Commande","answers":["pathping"],"e":"pathping calcule les statistiques de perte et de latence de chaque routeur du chemin, sur une période de plusieurs minutes."},
  {"theme":"diagnostic","level":"legende","format":"input","q":"Quelle cmdlet PowerShell affiche le cache ARP du poste ?","placeholder":"Cmdlet","answers":["Get-NetNeighbor"],"e":"Get-NetNeighbor liste les voisins connus avec leur adresse MAC et leur état. C'est l'équivalent de arp -a."},
  {"theme":"diagnostic","level":"legende","format":"input","q":"Quel numéro de type ICMP correspond à une demande d'écho (ping) ?","placeholder":"Numéro","answers":["8","type 8"],"e":"Type 8 : demande d'écho (echo request). Type 0 : réponse d'écho. Type 3 : destination injoignable. Type 11 : temps dépassé."},
  {"theme":"diagnostic","level":"legende","format":"input","q":"Quelle option de tcpdump évite la résolution des noms et des ports ? (deux lettres)","placeholder":"Option","answers":["-nn","-n"],"e":"Avec -nn, tcpdump affiche adresses et ports sous forme numérique. La capture est plus rapide et ne génère pas de requêtes DNS parasites."},
  {"theme":"diagnostic","level":"legende","format":"input","q":"Quel sigle désigne la fonction d'un commutateur qui recopie un port vers un autre pour permettre la capture ? (quatre lettres)","placeholder":"Sigle","answers":["SPAN","port span"],"e":"SPAN (Switched Port Analyzer), aussi appelé port mirroring, recopie le trafic d'un ou plusieurs ports vers un port d'analyse."}
);
